        const live = inkLiveRef.current;
        const view = wrapper.ownerDocument.defaultView;
        const scroller = scrollContainerRef.current?.getBoundingClientRect() ?? null;
        const clipLeft = Math.max(rect.left, scroller?.left ?? rect.left, 0);
        const clipTop = Math.max(rect.top, scroller?.top ?? rect.top, 0);
        const clipRight = Math.min(rect.right, scroller?.right ?? rect.right, view?.innerWidth ?? rect.right);
        const clipBottom = Math.min(rect.bottom, scroller?.bottom ?? rect.bottom, view?.innerHeight ?? rect.bottom);
        const style: InkLiveStyle = {
          color: gesture.color,
          widthPx,
          opacity: 1,
          // A pen's own pressure, or the pen's feel varying the width.
          pressure: down.pointerType === "pen" || Boolean(dynamics?.varies),
        };
        const liveRect = {
          left: clipLeft - rect.left,
          top: clipTop - rect.top,
          width: Math.max(1, clipRight - clipLeft),
          height: Math.max(1, clipBottom - clipTop),
        };
        gesture.liveRect = liveRect;
        gesture.liveStyle = style;
        gesture.live = live.begin(
          liveRect,
          style,
          1,
          { left: rect.left, top: rect.top, scale: 1 },
        );
