  // each value by its field kind so a stale / malformed persisted value can't be
  // rendered. Runs whenever the known-field set grows.
  useEffect(() => {
    const raw = nativeFormMode ? null : rawFormValuesRef.current;
    if (!raw || allFormFields.length === 0) return;
    const persisted = normalizeFormValues(raw, allFormFields);
    setFormValues((prev) => {
      const next = { ...prev };
      let changed = false;
      for (const [name, value] of Object.entries(persisted)) {
        if (formTouchedRef.current.has(name)) continue;
        if (next[name] !== value) {
          setFormValueEntry(next, name, value);
          changed = true;
        }
      }
      if (!changed) return prev;
      formValuesRef.current = next;
      return next;
    });
  }, [allFormFields, nativeFormMode]);

  // The page paints every widget itself (see renderPageInner). Keep pdf.js's
  // annotation storage in step with the value map and repaint the pages whose
  // widgets changed, so browsing, filling and editing show one and the same
  // control; the caret's own field shows a live editor meanwhile.
  const formAppearanceStorageRef = useRef<{
    document: PdfDocument | null;
    keys: Map<string, boolean | string | string[]>;
  }>({ document: null, keys: new Map() });
  const formAppearanceRepaintRef = useRef<{
    pages: Set<number>;
    timer: ReturnType<typeof setTimeout> | null;
  }>({ pages: new Set(), timer: null });
  useEffect(() => {
    const storage = (
      pdfDoc as { annotationStorage?: PdfAnnotationStorageLike } | null
    )?.annotationStorage;
    if (
      !pdfDoc ||
      !storage ||
      typeof storage.setValue !== "function" ||
      typeof storage.remove !== "function"
    ) {
      return;
    }
    const tracked = formAppearanceStorageRef.current;
    if (tracked.document !== pdfDoc) {
      tracked.document = pdfDoc;
      tracked.keys = new Map();
    }
    // Every password widget of the document, so an export or a layer render
    // of a page not shown yet leaves it out as the page does (PDF 0006).
    syncPdfPasswordWidgetStorage(
      storage,
      allFormFields.flatMap((field) => {
        const widgetId = field.password ? pdfWidgetIdForField(field.id) : null;
        return widgetId ? [widgetId] : [];
      }),
    );
    const { keys, changedFieldIds } = syncPdfFormAppearanceStorage(
      storage,
      allFormFields,
      formValues,
      tracked.keys,
      locale,
    );
    tracked.keys = keys;
    if (changedFieldIds.length === 0) return;
    const changed = new Set(changedFieldIds);
    const repaint = formAppearanceRepaintRef.current;
    for (const [pageNumber, fields] of formFields) {
      if (fields.some((field) => changed.has(field.id))) {
        repaint.pages.add(pageNumber);
      }
    }
    if (repaint.pages.size === 0 || repaint.timer) return;
    // A burst of keystrokes becomes one repaint per page.
    repaint.timer = setTimeout(() => {
      repaint.timer = null;
      const pages = [...repaint.pages];
      repaint.pages.clear();
      if (pdfDocRef.current !== pdfDoc) return;
      for (const pageNumber of pages) {
        if (!pageRefs.current.has(pageNumber)) continue;
        // A render already in flight for this page started before the value
        // changed and paints the old one; it is not yet in renderedPages, so
        // queue behind it instead of dropping this repaint. A page that is
        // still not rendered afterwards paints the current values when it
        // first renders.
        const inFlight =
          renderChainsRef.current.get(pageNumber) ?? Promise.resolve();
        void inFlight.then(() => {
          if (
            pdfDocRef.current !== pdfDoc ||
            !renderedPagesRef.current.has(pageNumber)
          ) {
            return;
          }
          renderedPagesRef.current.delete(pageNumber);
          void renderPage(pageNumber);
        });
      }
    }, 120);
  }, [allFormFields, formFields, formValues, pdfDoc, renderPage]);
  // Into the dark mode, the pages drawn are drawn again recording their
  // images, whose photos then keep their colours; out of it, the photos'
  // copies go (the filter is off, the page shows them itself).
  useEffect(() => {
    if (readModeRef.current === readMode) return;
    readModeRef.current = readMode;
    if (!pdfDoc) return;
    for (const [pageNumber, wrapper] of pageRefs.current) {
      if (readMode !== "invert") {
        const layer = wrapper.querySelector<HTMLElement>(":scope > [data-pdf-read-mode-photos]");
        if (layer) clearPdfReadModePhotos(layer);
        continue;
      }
      if (!renderedPagesRef.current.has(pageNumber)) continue;
      const inFlight = renderChainsRef.current.get(pageNumber) ?? Promise.resolve();
      void inFlight.then(() => {
        if (pdfDocRef.current !== pdfDoc || !renderedPagesRef.current.has(pageNumber)) return;
        renderedPagesRef.current.delete(pageNumber);
        void renderPage(pageNumber);
      });
    }
  }, [pdfDoc, readMode, renderPage]);
  useEffect(
    () => () => {
      const repaint = formAppearanceRepaintRef.current;
      if (repaint.timer) clearTimeout(repaint.timer);
      repaint.timer = null;
      repaint.pages.clear();
    },
    [],
  );

  // Persist the reader map or drain completed native gestures in FIFO order.
  // Native text gestures remain open until blur; a window/history flush closes
  // them explicitly so an idle pause cannot split one typing interaction into
  // several Undo entries.
  const flushFormValues: (options?: {
    includeOpenNativeGesture?: boolean;
  }) => Promise<boolean> = useCallback(
    async (options: { includeOpenNativeGesture?: boolean } = {}) => {
      if (!dataItemId) return false;
      const nativeAuthority = nativeFormWriteAuthorityRef.current;
      if (nativeAuthority && options.includeOpenNativeGesture) {
        for (const gesture of pendingNativeFormGesturesRef.current) {
          gesture.closed = true;
        }
        activeNativeFormGestureRef.current = null;
        // Publish the complete final intent before the first await. The parent
        // can therefore take custody during close/page cleanup even when an
        // older gesture is still in flight and this call returns early.
        publishNativeFormPending();
      }
      if (formSavingRef.current) {
        formDirtyWhileSavingRef.current = true;
        publishNativeFormPending();
        return false;
      }
      if (nativeAuthority) {
        if (!nativeAuthority.writable || !nativeFormFieldChangeRef.current) {
          return false;
        }
        formSavingRef.current = true;
        publishNativeFormPending();
        let acceptedAll = true;
        try {
          while (true) {
            const gesture = pendingNativeFormGesturesRef.current[0];
            if (!gesture || !gesture.closed) break;
            const currentAuthority = nativeFormWriteAuthorityRef.current;
            if (
              !currentAuthority?.writable ||
              currentAuthority.generation !== gesture.generation
            ) {
              acceptedAll = false;
              break;
            }
            const currentCommit = nativeFormFieldChangeRef.current;
            if (!currentCommit) {
              acceptedAll = false;
              break;
            }
            const accepted = await currentCommit({
              generation: gesture.generation,
              gestureId: gesture.id,
              fields: [...gesture.fields.values()],
            });
            const current = pendingNativeFormGesturesRef.current[0];
            if (accepted !== true) {
              acceptedAll = false;
              break;
            }
            // The host durably wrote this gesture. Its save publishes a new
            // revision, which may already have retired the FIFO it sat in:
            
            if (current === gesture) {
              pendingNativeFormGesturesRef.current.shift();
              publishNativeFormPending();
            }
            if (
              nativeFormWriteAuthorityRef.current?.generation !==
              gesture.generation
            ) {
              break;
            }
          }
          return (
            acceptedAll && pendingNativeFormGesturesRef.current.length === 0
          );
        } catch {
          // Keep the exact gesture at the head of the FIFO. A later explicit
          // flush can retry it; never fall back to the reader annotation store.
          return false;
        } finally {
          formSavingRef.current = false;
          const retry = formDirtyWhileSavingRef.current;
          formDirtyWhileSavingRef.current = false;
          publishNativeFormPending();
          if (
            retry &&
            pendingNativeFormGesturesRef.current.some(
              (gesture) => gesture.closed,
            ) &&
            !formSaveTimerRef.current
          ) {
            formSaveTimerRef.current = setTimeout(() => {
              formSaveTimerRef.current = null;
              void flushFormValues();
            }, 0);
          }
        }
      }

      const payloadValues = buildFormValuesPayload(
        formValuesRef.current,
        allFormFields,
      );
      formSavingRef.current = true;
      try {
        const body = { values: payloadValues };
        if (formValuesIdRef.current) {
          await apiPatch(`/api/v1/annotations/${formValuesIdRef.current}`, {
            payload_json: body,
          });
        } else {
          const result = await apiPost<{ annotation: { id: string } }>(
            `/api/v1/data-items/${dataItemId}/annotations`,
            { type: "pdf_form_values", payload_json: body },
          );
          formValuesIdRef.current = result.annotation.id;
        }
        return true;
      } catch {
        return false;
      } finally {
        formSavingRef.current = false;
        const retry = formDirtyWhileSavingRef.current;
        formDirtyWhileSavingRef.current = false;
        if (retry && !formSaveTimerRef.current) {
          formSaveTimerRef.current = setTimeout(() => {
            formSaveTimerRef.current = null;
            void flushFormValues();
          }, 0);
        }
      }
    },
    [allFormFields, dataItemId, publishNativeFormPending],
  );

  const scheduleFormSave = useCallback(() => {
    publishNativeFormPending();
    if (formSavingRef.current) {
      formDirtyWhileSavingRef.current = true;
      return;
    }
    if (formSaveTimerRef.current) clearTimeout(formSaveTimerRef.current);
    formSaveTimerRef.current = setTimeout(
      () => {
        formSaveTimerRef.current = null;
        void flushFormValues();
      },
      nativeFormWriteAuthorityRef.current ? 0 : 600,
    );
  }, [flushFormValues, publishNativeFormPending]);
  nativeFormRebasedSaveRef.current = scheduleFormSave;

  useLayoutEffect(() => {
    if (!nativeFormMode) {
      onNativeFormFlushReady?.(null);
      return;
    }
    onNativeFormFlushReady?.(() =>
      flushFormValues({ includeOpenNativeGesture: true }),
    );
    publishNativeFormPending();
    // The parent deliberately retains the last generation-bound function until
    // its own layout cleanup. It calls this seam before handing the departing
    // page draft to autosave; the generation check rejects any stale reuse.
  }, [
    flushFormValues,
    nativeFormMode,
    nativeFormWriteAuthority?.generation,
    onNativeFormFlushReady,
    publishNativeFormPending,
  ]);

  // Reader-owned edits live outside a native page's content_json model. Report
  // them separately so a host can fail closed instead of downloading an
  // original-package writeback that silently omits these visible edits. Form
  // values stop being reader-only when the host supplies the native callback:
  // each value then crosses the content_json → original-package bridge.
  // Key count is a primitive so the memo only recomputes when a field is first
  // added/removed — setFormValues makes a fresh object on every field edit, so
  // depending on `formValues` itself would recompute this boolean per keystroke.
  const formValuesCount = Object.keys(formValues).length;
  // A native host callback only proves that the edit entered the host's pending
  // patchback model; it does NOT prove the fetched `url` bytes already contain
  // that edit. Keep every field touched in this viewer session in the exact
  // compression loss manifest until a future source-generation receipt can
  // prove otherwise. The formValues state update re-renders this ref-backed
  // predicate, and buildAnnotatedPdfBytes' identity still advances the shared
  // edit revision so consent and the final sink both reject a later field edit.
  const hasNativeFormEditsExcludedFromSource =
    nativeFormMode && formTouchedRef.current.size > 0;
  const readerOnlyHighlightCount = highlights.filter(
    (highlight) =>
      !highlight.nativeMarkup ||
      (highlight.links?.length ?? 0) > 0 ||
      (highlight.replies?.length ?? 0) > 0,
  ).length;
  // A shape the window changed by itself -- an Undo or Redo of a shape
  // edit, saved or held for Save -- is the reader's shape as it now is: the
  // reader's copy (and its row) take it. Kept, the overlay went on drawing
  // the shape where it was before the Undo while the page drew it where the
  // Undo put it (two shapes). Only what changed in the window's records
  // since it last said is taken, so a shape being edited here (its record
  // not yet updated) is left to that edit.
  // Opened, the reader's rows are set to the shapes the PDF holds: a row
  // changed by an edit that was never saved (AutoSave off, then 不保存, a
  // reload, a failed Save) drew the shape a second time where that edit had
  // put it. Once per document opened, before anything is edited in it.
  const reconciledShapesItemRef = useRef<string | null>(null);
  useEffect(() => {
    if (!shapesHydratedItem || shapesHydratedItem !== dataItemId ||
      reconciledShapesItemRef.current === shapesHydratedItem || !nativeShapes?.length) return;
    reconciledShapesItemRef.current = shapesHydratedItem;
    const native = new Map(nativeShapes.map((shape) => [shape.id, shape]));
    const stale = shapesRef.current.flatMap((shape) => {
      const saved = native.get(shape.id);
      return saved && !isManagedNativeShapeEquivalent(shape, saved) ? [saved] : [];
    });
    if (stale.length === 0) return;
    if (process.env.NODE_ENV !== "production") {
      console.debug("[pdf-shape] rows set to the saved shapes", stale.map((shape) => shape.id.slice(0, 8)));
    }
    setShapes((current) => current.map((shape) => stale.find((saved) => saved.id === shape.id) ?? shape));
    void Promise.allSettled(stale.map((shape) => {
      const payload = buildShapePayload({
        page: shape.page, kind: shape.kind, x1: shape.x1, y1: shape.y1, x2: shape.x2, y2: shape.y2,
        points: shape.points, xfdfSourceId: shape.xfdfSourceId, color: shape.color, width: shape.width,
        lineStyle: shape.lineStyle, lineStart: shape.lineStart, lineEnd: shape.lineEnd, purpose: shape.purpose,
        fillColor: shape.fillColor, fillOpacity: shape.fillOpacity, opacity: shape.opacity,
        cornerRadius: shape.cornerRadius,
      });
      return payload ? apiPatch(`/api/v1/annotations/${shape.id}`, { payload_json: payload }) : Promise.resolve();
    })).then(() => advanceShapeMutationEpoch());
  }, [advanceShapeMutationEpoch, dataItemId, nativeShapes, shapesHydratedItem]);
  useEffect(() => {
    if (!discardedReaderRowIds?.size) return;
    setShapes((current) => (current.some((shape) => discardedReaderRowIds.has(shape.id))
      ? current.filter((shape) => !discardedReaderRowIds.has(shape.id)) : current));
    // An ink stroke the window's Undo took away: off the page at once, not
    
    setInks((current) => (current.some((ink) => discardedReaderRowIds.has(ink.id))
      ? current.filter((ink) => !discardedReaderRowIds.has(ink.id)) : current));
  }, [discardedReaderRowIds]);
  const previousNativeShapesRef = useRef<{
    dataItemId: string | null | undefined;
    shapes: ReadonlyMap<string, ShapeAnnotation>;
  } | null>(null);
  useEffect(() => {
    const next = new Map((nativeShapes ?? []).map((shape) => [shape.id, shape]));
    const before = previousNativeShapesRef.current;
    previousNativeShapesRef.current = { dataItemId, shapes: next };
    // Another document's shapes are not a change of these.
    if (!before || before.dataItemId !== dataItemId) return;
    const previous = before.shapes;
    const reader = new Map(shapesRef.current.map((shape) => [shape.id, shape]));
    const adopt: ShapeAnnotation[] = [];
    for (const [id, shape] of next) {
      const before = previous.get(id);
      if (before && isManagedNativeShapeEquivalent(before, shape)) continue;
      const shown = reader.get(id);
      if (!shown || !isManagedNativeShapeEquivalent(shown, shape)) adopt.push(shape);
    }
    const drop = [...previous.keys()].filter((id) => !next.has(id) && reader.has(id));
    if (adopt.length === 0 && drop.length === 0) return;
    if (process.env.NODE_ENV !== "production") {
      console.debug("[pdf-shape] adopt", JSON.stringify({ adopt: adopt.map((shape) => [shape.id.slice(0, 8), shape.x1, shape.y1, shape.x2, shape.y2]), drop }));
    }
    setShapes((current) => {
      let out = current.filter((shape) => !drop.includes(shape.id));
      for (const shape of adopt) out = upsertAnnotationRowById(out, shape);
      return out;
    });
    // A shape still standing where it was dropped (its lift, until the page
    // paints its write) goes where the window's record puts it: a held
    // move's Undo writes no revision for the lift to wait for.
    const moved = new Set([...adopt.map((shape) => `shape:${shape.id}`), ...drop.map((id) => `shape:${id}`)]);
    setNativeVectorDragGhost((latest) => (latest && moved.has(latest.key) ? null : latest));
    setParkedCanvasObjectLifts((list) => (list.some((entry) => moved.has(entry.key))
      ? list.filter((entry) => !moved.has(entry.key)) : list));
    const rowWrites: Promise<unknown>[] = [];
    for (const shape of adopt) {
      if (!reader.has(shape.id)) continue;
      const payload = buildShapePayload({
        page: shape.page, kind: shape.kind, x1: shape.x1, y1: shape.y1, x2: shape.x2, y2: shape.y2,
        points: shape.points, xfdfSourceId: shape.xfdfSourceId, color: shape.color, width: shape.width,
        lineStyle: shape.lineStyle, lineStart: shape.lineStart, lineEnd: shape.lineEnd, purpose: shape.purpose,
        fillColor: shape.fillColor, fillOpacity: shape.fillOpacity, opacity: shape.opacity,
        cornerRadius: shape.cornerRadius,
      });
      if (payload) rowWrites.push(apiPatch(`/api/v1/annotations/${shape.id}`, { payload_json: payload }));
    }
    // The rows are read again once they are written: read before, they
    // gave the reader back the place the Undo had just taken it from.
    if (rowWrites.length > 0) {
      void Promise.allSettled(rowWrites).then(() => advanceShapeMutationEpoch());
    }
  }, [advanceShapeMutationEpoch, dataItemId, nativeShapes]);
  const { managedNativeShapeIdSet, readerOnlyShapeCount } = useMemo(() => {
    const nativeById = new Map(
      (nativeShapes ?? []).map((shape) => [shape.id, shape]),
    );
    const syncedIds = new Set<string>();
    // Start with every native object: a native shape missing from the reader
    // store is a failed delete (or corrupt join) and must block native export.
    const mismatchedIds = new Set(nativeById.keys());
    for (const readerShape of shapes) {
      const nativeShape = nativeById.get(readerShape.id);
      if (
        nativeShape &&
        !heldNativeAnnotations?.ids.shape.has(readerShape.id) &&
        isManagedNativeShapeEquivalent(readerShape, nativeShape)
      ) {
        syncedIds.add(readerShape.id);
        mismatchedIds.delete(readerShape.id);
      } else {
        // Includes reader-only creates and same-id geometry/style mismatches.
        mismatchedIds.add(readerShape.id);
      }
    }
    return {
      managedNativeShapeIdSet: syncedIds,
      readerOnlyShapeCount: mismatchedIds.size,
    };
  }, [heldNativeAnnotations, nativeShapes, shapes]);
  const { managedNativeSignatureIdSet, readerOnlySignatureCount } =
    useMemo(() => {
      const nativeById = new Map(
        (nativeSignatures ?? []).map((signature) => [signature.id, signature]),
      );
      const syncedIds = new Set<string>();
      const mismatchedIds = new Set(nativeById.keys());
      for (const readerSignature of signatures) {
        const nativeSignature = nativeById.get(readerSignature.id);
        if (
          nativeSignature &&
          !heldNativeAnnotations?.ids.signature.has(readerSignature.id) &&
          isManagedNativeSignatureEquivalent(readerSignature, nativeSignature)
        ) {
          syncedIds.add(readerSignature.id);
          mismatchedIds.delete(readerSignature.id);
        } else {
          // Includes legacy reader-only rows and semantic/appearance mismatch.
          mismatchedIds.add(readerSignature.id);
        }
      }
      return {
        managedNativeSignatureIdSet: syncedIds,
        readerOnlySignatureCount: mismatchedIds.size,
      };
    }, [heldNativeAnnotations, nativeSignatures, signatures]);
  const { managedNativeStampIdSet, readerOnlyStampCount } = useMemo(() => {
    const nativeById = new Map(
      (nativeStamps ?? []).map((stamp) => [stamp.id, stamp]),
    );
    const syncedIds = new Set<string>();
    const mismatchedIds = new Set(nativeById.keys());
    for (const readerStamp of stamps) {
      const nativeStamp = nativeById.get(readerStamp.id);
      if (
        nativeStamp &&
        !heldNativeAnnotations?.ids.stamp.has(readerStamp.id) &&
        isManagedNativeStampEquivalent(readerStamp, nativeStamp)
      ) {
        syncedIds.add(readerStamp.id);
        mismatchedIds.delete(readerStamp.id);
      } else {
        // Includes legacy reader-only rows and geometry/content mismatches.
        // They retain the explicit flattened export path.
        mismatchedIds.add(readerStamp.id);
      }
    }
    return {
      managedNativeStampIdSet: syncedIds,
      readerOnlyStampCount: mismatchedIds.size,
    };
  }, [heldNativeAnnotations, nativeStamps, stamps]);
  const { managedNativeLinkIdSet, readerOnlyLinkCount } = useMemo(() => {
    const nativeById = new Map(
      (nativeLinks ?? []).map((link) => [link.id, link]),
    );
    const syncedIds = new Set<string>();
    const mismatchedIds = new Set(nativeById.keys());
    for (const readerLink of linkOverlays) {
      const nativeLink = nativeById.get(readerLink.id);
      if (nativeLink && !heldNativeAnnotations?.ids.link.has(readerLink.id) &&
        isManagedNativeLinkEquivalent(readerLink, nativeLink)) {
        syncedIds.add(readerLink.id);
        mismatchedIds.delete(readerLink.id);
      } else {
        mismatchedIds.add(readerLink.id);
      }
    }
    return {
      managedNativeLinkIdSet: syncedIds,
      readerOnlyLinkCount: mismatchedIds.size,
    };
  }, [heldNativeAnnotations, linkOverlays, nativeLinks]);
  const readerOnlyMeasurementCount =
    nativeMeasurements === undefined ? localMeasurements.length : 0;
  const hasReaderExportEdits = useMemo(
    () =>
      readerOnlyHighlightCount > 0 ||
      notes.length > 0 ||
      inks.length > 0 ||
      redactions.length > 0 ||
      readerOnlyShapeCount > 0 ||
      readerOnlySignatureCount > 0 ||
      readerOnlyStampCount > 0 ||
      readerOnlyLinkCount > 0 ||
      readerOnlyMeasurementCount > 0 ||
      userBookmarks.length > 0 ||
      (!nativeFormMode && formValuesCount > 0) ||
      pageLabelRanges.length > 0 ||
      (!documentDecorationsNative &&
        hasPdfDocumentDecorations(effectiveDocumentDecorations)),
    [
      readerOnlyHighlightCount,
      notes.length,
      inks.length,
      redactions.length,
      readerOnlyShapeCount,
      readerOnlySignatureCount,
      readerOnlyStampCount,
      readerOnlyLinkCount,
      readerOnlyMeasurementCount,
      userBookmarks.length,
      formValuesCount,
      nativeFormMode,
      pageLabelRanges.length,
      documentDecorationsNative,
      effectiveDocumentDecorations,
    ],
  );
  useEffect(() => {
    onReaderExportEditsChange?.(hasReaderExportEdits);
  }, [hasReaderExportEdits, onReaderExportEditsChange]);
  const readerExportEditCount =
    readerOnlyHighlightCount +
    notes.length +
    inks.length +
    redactions.length +
    readerOnlyShapeCount +
    readerOnlySignatureCount +
    readerOnlyStampCount +
    readerOnlyLinkCount +
    readerOnlyMeasurementCount +
    userBookmarks.length +
    (nativeFormMode ? 0 : formValuesCount) +
    pageLabelRanges.length +
    (documentDecorationsNative
      ? 0
      : (effectiveDocumentDecorations.watermark ? 1 : 0) +
        (effectiveDocumentDecorations.pageNumber ? 1 : 0) +
        (effectiveDocumentDecorations.headerFooter ? 1 : 0));
  useEffect(() => {
    onReaderExportEditCountChange?.(readerExportEditCount);
  }, [onReaderExportEditCountChange, readerExportEditCount]);

  // True when there is at least one visible or document-level edit worth
  // baking into a local download.
  const hasFlattenableAnnotations = useMemo(
    () =>
      hasReaderExportEdits ||
      (nativeInkStrokes?.length ?? 0) > 0 ||
      (nativeImageOverlays?.length ?? 0) > 0 ||
      (textBoxEdits?.length ?? 0) > 0 ||
      (cropBoxes?.length ?? 0) > 0 ||
      // Structural page edits (rotate / delete / reorder / insert / duplicate)
      // bake through the same pipeline, so they alone enable the download.
      !isEmptyPageEditState(pageEdits),
    [
      hasReaderExportEdits,
      nativeInkStrokes?.length,
      nativeImageOverlays?.length,
      textBoxEdits?.length,
      cropBoxes?.length,
      pageEdits,
    ],
  );
  // A live mask and fail-safe unknown hydration both make "current" a derived
  // output. Only an authenticated current-document hydration can safely bake
  // that state; neither case may fall back to a read-only/original shortcut.
  const hasEffectivePdfOutputEdits =
    hasFlattenableAnnotations ||
    visualMaskOutputRiskPresent ||
    redactionOutputRiskPresent;
  const hasEffectivePdfOutputEditsRef = useRef(hasEffectivePdfOutputEdits);
  hasEffectivePdfOutputEditsRef.current = hasEffectivePdfOutputEdits;
  const canSafelyBuildVisualMaskOutput =
    shapesHydratedForCurrentDocument && visualMaskWritesInFlight === 0;
  const canAdmitVisualMaskDerivedPdfOutput =
    canSafelyBuildVisualMaskOutput &&
    (savePolicyV1 || !visualMaskOutputRiskPresent);
  formValueEditorEditsRef.current =
    hasFlattenableAnnotations || hasNativeFormEditsExcludedFromSource;

  // Build the same normalized decoration layers shown by the editor preview.
  // `sourcePageOrder` preserves range semantics while structural edits choose
  // the exported sequence independently.
  const buildExportStampConfig = useCallback(
    (sourcePageOrder: readonly number[]) =>
      documentDecorationsNative
        ? null
        : buildPdfDecorationFlattenConfig(
            effectiveDocumentDecorations,
            sourcePageOrder,
          ),
    [documentDecorationsNative, effectiveDocumentDecorations],
  );

  const [xfdfImportBusy, setXfdfImportBusy] = useState(false);
  const xfdfImportBusyRef = useRef(false);
  const xfdfInputRef = useRef<HTMLInputElement | null>(null);
  const xfdfImportDocumentKey = [
    dataItemId ?? "",
    filename ?? "",
    matchedSourceRiskSnapshot?.identity.sha256 ?? sourceSha256 ?? "",
    sourceDocumentRevision ?? "",
    sourceByteGenerationKey ?? "",
  ].join(":");
  const [pendingUnboundXfdfImport, setPendingUnboundXfdfImport] = useState<{
    file: File;
    parsed: ParsedXfdf;
    documentKey: string;
  } | null>(null);
  useEffect(() => {
    setPendingUnboundXfdfImport((current) =>
      current && current.documentKey !== xfdfImportDocumentKey ? null : current,
    );
  }, [xfdfImportDocumentKey]);

  /**
   * Read an XFDF file back into the reader.
   *
   * Merges on the annotation id XFDF carries as `name`: a comment we already
   * hold is left alone rather than duplicated, so re-importing the file a
   * supervisor sent twice does not double every highlight. Anything the reader's
   * own model cannot hold faithfully — unsupported shapes or a page the document
   * does not have — is counted and reported instead of being quietly dropped or
   * clamped.
   */
  const importXfdfFile = useCallback(
    async (
      file: File,
      allowUnbound = false,
      expectedDocumentKey?: string,
      preparsed?: ParsedXfdf,
    ) => {
      if (
        !dataItemId ||
        xfdfImportBusyRef.current ||
        (expectedDocumentKey !== undefined &&
          expectedDocumentKey !== xfdfImportDocumentKey)
      ) {
        if (
          expectedDocumentKey !== undefined &&
          expectedDocumentKey !== xfdfImportDocumentKey
        ) {
          setXfdfImportNotice(t("pdfViewer.importXfdfWrongDocument"));
        }
        return;
      }
      xfdfImportBusyRef.current = true;
      setXfdfImportBusy(true);
      setXfdfImportNotice(null);
      try {
        if (file.size > XFDF_MAX_FILE_BYTES) {
          throw new Error(t("pdfViewer.importXfdfFailed"));
        }
        const parsed = preparsed ?? fromXfdf(await file.text());
        if (!parsed.valid) {
          throw new Error(t("pdfViewer.importXfdfFailed"));
        }
        const documentMatch = matchXfdfDocument(parsed, {
          filename,
          sourceSha256:
            matchedSourceRiskSnapshot?.identity.sha256 ?? sourceSha256,
        });
        if (documentMatch === "mismatch") {
          setXfdfImportNotice(t("pdfViewer.importXfdfWrongDocument"));
          return;
        }
        if (documentMatch === "unbound" && !allowUnbound) {
          setPendingUnboundXfdfImport({
            file,
            parsed,
            documentKey: xfdfImportDocumentKey,
          });
          return;
        }
        const sizeByPage = new Map<number, FlattenPageSize>();
        pages.forEach((p) =>
          sizeByPage.set(p.pageNumber, {
            width: p.width,
            height: p.height,
            rotation: resolvedPageRotation(p.pageNumber),
            originX: p.originX,
            originY: p.originY,
          }),
        );
        const { annotations: incoming, skipped } = importXfdfAnnotations(
          parsed.annotations,
          sizeByPage,
        );
        let skippedCount =
          skipped +
          parsed.unsupportedAnnotationCount +
          parsed.orphanReplies.length +
          parsed.annotations.reduce(
            (total, annotation) => total + annotation.replies.length,
            0,
          );
        const knownIds = new Set<string>([
          ...highlights.map((h) => h.id),
          ...notes.map((n) => n.id),
          ...inks.map((stroke) => stroke.id),
          ...shapes.map((shape) => shape.id),
        ]);
        const knownXfdfSourceIds = new Set(
          [...highlights, ...notes, ...inks, ...shapes]
            .map((annotation) => annotation.xfdfSourceId)
            .filter((id): id is string => Boolean(id)),
        );
        const shapeCountsByPage = new Map<number, number>();
        for (const shape of shapes) {
          shapeCountsByPage.set(
            shape.page,
            (shapeCountsByPage.get(shape.page) ?? 0) + 1,
          );
        }
        const anonymousOccurrences = new Map<string, number>();
        let added = 0;
        for (const item of incoming) {
          const firstIdentity = xfdfSourceIdentity(item);
          const namedIdentity = normalizeXfdfSourceId(item.id);
          const duplicateOccurrence = namedIdentity
            ? 0
            : (anonymousOccurrences.get(firstIdentity) ?? 0);
          if (!namedIdentity) {
            anonymousOccurrences.set(firstIdentity, duplicateOccurrence + 1);
          }
          const xfdfSourceId = xfdfSourceIdentity(
            item,
            duplicateOccurrence,
          );
          if (
            (item.id && knownIds.has(item.id)) ||
            (item.kind !== "ink" && knownXfdfSourceIds.has(xfdfSourceId))
          ) {
            // The same annotation again. Identical content is a no-op; a
            // changed comment is the reviewer's update and is applied to the
            // annotation already here (its identity, position, author and
            // thread kept) rather than dropped as "0 imported, 0 skipped"
            
            if (item.kind === "note") {
              const existing = notes.find(
                (note) =>
                  (item.id && note.id === item.id) ||
                  note.xfdfSourceId === xfdfSourceId,
              );
              if (existing && existing.text !== item.text) {
                const payload = buildNotePayload({
                  page: existing.page,
                  x: existing.x,
                  y: existing.y,
                  text: item.text,
                  color: existing.color,
                  resolved: existing.resolved,
                  author: existing.author,
                  replies: existing.replies,
                  xfdfSourceId: existing.xfdfSourceId,
                });
                await threadWriter.write(existing.id, payload, "mine");
                await syncManagedNote({ ...existing, text: payload.text });
                setNotes((prev) =>
                  prev.map((note) =>
                    note.id === existing.id ? { ...note, text: payload.text } : note,
                  ),
                );
                added += 1;
              }
            } else if (item.kind === "highlight") {
              const existing = highlights.find(
                (highlight) =>
                  (item.id && highlight.id === item.id) ||
                  highlight.xfdfSourceId === xfdfSourceId,
              );
              const nextNote = item.note ?? "";
              if (existing && (existing.note ?? "") !== nextNote) {
                const updated = { ...existing, note: nextNote, text: nextNote };
                await threadWriter.write(
                  existing.id,
                  buildHighlightReaderPayload(updated),
                  "mine",
                );
                setHighlights((prev) =>
                  prev.map((highlight) =>
                    highlight.id === existing.id ? updated : highlight,
                  ),
                );
                added += 1;
              }
            }
            continue;
          }
          if (item.kind === "highlight") {
            const payload = {
              page: item.page,
              text: item.note ?? "",
              color: item.color ?? DEFAULT_HIGHLIGHT_COLOR,
              rects: item.rects,
              ...(item.quads ? { quads: item.quads } : {}),
              style: item.markupStyle,
              ...(item.note ? { note: item.note } : {}),
              xfdfSourceId,
              ...(item.authorName
                ? { author: xfdfAuthorIdentity(item.authorName) }
                : {}),
            };
            const result = await apiPost<{ annotation: { id: string } }>(
              `/api/v1/data-items/${dataItemId}/annotations`,
              { type: "pdf_highlight", payload_json: payload },
            );
            setHighlights((current) => [
              ...current,
              {
                id: result.annotation.id,
                page: item.page,
                text: item.note ?? "",
                color: payload.color,
                rects: item.rects,
                ...(item.quads ? { quads: item.quads } : {}),
                markupStyle: item.markupStyle,
                xfdfSourceId,
                ...(item.note ? { note: item.note } : {}),
              },
            ]);
          } else if (item.kind === "ink") {
            // XFDF carries plain polylines; the converted stroke is uniform
            // width — honest about what the file said, not inventing the
            // pressure it never recorded.
            let importedGesture = false;
            for (const [gestureIndex, gesture] of item.strokes.entries()) {
              const gestureSourceId = xfdfInkGestureSourceIdentity(
                xfdfSourceId,
                gestureIndex,
              );
              if (knownXfdfSourceIds.has(gestureSourceId)) continue;
              const points: Array<{ x: number; y: number }> = [];
              for (let at = 0; at + 1 < gesture.length; at += 2) {
                points.push({ x: gesture[at], y: gesture[at + 1] });
              }
              if (points.length < 2) continue;
              const payload = buildInkPayload({
                page: item.page,
                color: item.color,
                width: item.width,
                points,
                xfdfSourceId: gestureSourceId,
              });
              const result = await apiPost<{ annotation: { id: string } }>(
                `/api/v1/data-items/${dataItemId}/annotations`,
                { type: "pdf_ink", payload_json: payload },
              );
              setInks((current) => [
                ...current,
                {
                  id: result.annotation.id,
                  page: payload.page,
                  color: payload.color,
                  width: payload.width,
                  points: payload.points,
                  xfdfSourceId: gestureSourceId,
                },
              ]);
              knownXfdfSourceIds.add(gestureSourceId);
              importedGesture = true;
            }
            if (importedGesture) added += 1;
            continue;
          } else if (item.kind === "shape") {
            const shapeCount = shapeCountsByPage.get(item.page) ?? 0;
            if (shapeCount >= PDF_SHAPE_MAX_PER_PAGE) {
              skippedCount += 1;
              continue;
            }
            const payload = buildShapePayload({
              page: item.page,
              kind: item.shapeKind,
              x1: item.x1,
              y1: item.y1,
              x2: item.x2,
              y2: item.y2,
              points: item.points,
              color: item.color,
              width: item.width,
              fillColor: item.fillColor,
              fillOpacity: item.fillOpacity,
              opacity: item.opacity,
              cornerRadius: item.cornerRadius,
              lineStyle: item.lineStyle,
              lineStart: item.lineStart,
              lineEnd: item.lineEnd,
              xfdfSourceId,
            });
            if (!payload) {
              skippedCount += 1;
              continue;
            }
            const result = await apiPost<{ annotation: { id: string } }>(
              `/api/v1/data-items/${dataItemId}/annotations`,
              { type: "pdf_shapes", payload_json: payload },
            );
            const created: ShapeAnnotation = {
              id: result.annotation.id,
              ...payload,
              fillColor: payload.fillColor ?? null,
            };
            if (!advanceShapeMutationEpoch()) continue;
            if (onManagedShapeUpsert) {
              try {
                await onManagedShapeUpsert(created);
              } catch (error) {
                await apiDelete(`/api/v1/annotations/${created.id}`).catch(
                  () => undefined,
                );
                advanceShapeMutationEpoch();
                throw error;
              }
            }
            setShapes((current) => [...current, created]);
            shapeCountsByPage.set(item.page, shapeCount + 1);
          } else {
            const payload = {
              page: item.page,
              x: item.x,
              y: item.y,
              text: item.text,
              color: item.color ?? PDF_NOTE_COLORS[0],
              xfdfSourceId,
              // The file's author (its XFDF `title`) stays the note's shown
              // author, distinct from any platform account; it was dropped
              
              ...(item.authorName
                ? { author: xfdfAuthorIdentity(item.authorName) }
                : {}),
            };
            const result = await apiPost<{ annotation: { id: string } }>(
              `/api/v1/data-items/${dataItemId}/annotations`,
              { type: "pdf_note", payload_json: payload },
            );
            setNotes((current) => [
              ...current,
              { id: result.annotation.id, ...payload },
            ]);
          }
          knownXfdfSourceIds.add(xfdfSourceId);
          added += 1;
        }
        setXfdfImportNotice(
          t("pdfViewer.importXfdfDone", { added, skipped: skippedCount }),
        );
      } catch (error) {
        setXfdfImportNotice(
          error instanceof Error
            ? error.message
            : t("pdfViewer.importXfdfFailed"),
        );
      } finally {
        xfdfImportBusyRef.current = false;
        setXfdfImportBusy(false);
        if (xfdfInputRef.current) xfdfInputRef.current.value = "";
      }
    },
    [
      setXfdfImportNotice,
      advanceShapeMutationEpoch,
      dataItemId,
      filename,
      highlights,
      inks,
      matchedSourceRiskSnapshot,
      notes,
      onManagedShapeUpsert,
      pages,
      resolvedPageRotation,
      shapes,
      sourceSha256,
      syncManagedNote,
      t,
      threadWriter,
      xfdfImportDocumentKey,
    ],
  );

  const handleImportXfdfFile = useCallback(
    async (fileList: FileList | null) => {
      const file = fileList?.[0];
      if (!file) return;
      await importXfdfFile(file);
    },
    [importXfdfFile],
  );

  const confirmUnboundXfdfImport = useCallback(() => {
    const pending = pendingUnboundXfdfImport;
    if (!pending) return;
    setPendingUnboundXfdfImport(null);
    void importXfdfFile(
      pending.file,
      true,
      pending.documentKey,
      pending.parsed,
    );
  }, [importXfdfFile, pendingUnboundXfdfImport]);
  // MRAI's own comments: what "download with editable comments" writes.
  const hasEditableXfdfAnnotations =
    highlights.length > 0 ||
    notes.length > 0 ||
    inks.length > 0 ||
    shapes.some(canRoundTripShapeThroughXfdf);

  const buildAnnotatedPdfBytes = useCallback(
    async (
      buildOptions: {
        keepFormFillable?: boolean;
        metadata?: PdfMetadata;
        /** Export highlights + notes as real annotations rather than pixels. */
        editableAnnotations?: boolean;
        /** Exact irreversible intent; only pdf.redaction.apply may set this. */
        applyRedactions?: boolean;
        /**
         * Caller-owned source snapshot that was already bound to the current
         * document identity. Print uses this to prevent a second mutable-URL
         * fetch after its source SHA has been reviewed.
         */
        verifiedSourceBytes?: Uint8Array;
      } = {},
    ): Promise<Uint8Array> => {
      const applyRedactions = buildOptions.applyRedactions === true;
      if (redactions.length > 0 && !applyRedactions) {
        throw new Error(redactionProductCopy.blockedOutput);
      }
      if (applyRedactions && redactions.length === 0) {
        throw new Error(redactionProductCopy.failure);
      }
      if (applyRedactions && !pdfRedactionReachabilityV2Enabled()) {
        throw new Error(redactionProductCopy.failure);
      }
      let sourceBytes: Uint8Array;
      if (buildOptions.verifiedSourceBytes) {
        sourceBytes = new Uint8Array(
          buildOptions.verifiedSourceBytes.byteLength,
        );
        sourceBytes.set(buildOptions.verifiedSourceBytes);
      } else {
        const response = await fetchPdfSource(url);
        if (!response.ok) {
          throw new Error(`${response.status} ${response.statusText}`.trim());
        }
        sourceBytes = new Uint8Array(await response.arrayBuffer());
      }

      // Per-page unrotated media-box sizes (pdf.js scale-1.0 dims) + the resolved
      // display rotation, so the planner maps rendered-percent coords back into
      // PDF user space rotation-aware.
      // The crop box's corner too: the percent model measures from the
      // visible box, and a page cropped to one line had every baked box
      // drawn as if the crop began at 0,0 -- outside the page's visible part
      
      // y 785).
      const pageSizes: FlattenPageSize[] = pages.map((p) => ({
        width: p.width,
        height: p.height,
        rotation: resolvedPageRotation(p.pageNumber),
        originX: p.originX,
        originY: p.originY,
      }));

      // Re-extract only pages with mixed-format or old native-hit text edits. Persisted
      // runs intentionally omit document-scoped pdf.js font aliases, but the
      // live document can recover them from its embedded @font-face objects for
      // a pixel-faithful raster export. Failure is non-fatal: stable source font
      // names/families remain as the fallback.
      const sourceTextBoxes: PdfViewerTextBoxCommandTarget[] = [];
      const needsSourceTextLayout = (edit: {
        id?: string;
        runs?: readonly unknown[];
      }) =>
        Boolean(
          edit.runs?.length || /^native-text:\d+:\d+:\d+$/.test(edit.id ?? ""),
        );
      if (pdfDoc && textBoxEdits?.some(needsSourceTextLayout)) {
        const editedPages = Array.from(
          new Set(
            textBoxEdits
              .filter(needsSourceTextLayout)
              .map((edit) => Math.max(0, Math.trunc(Number(edit.page) || 0))),
          ),
        );
        for (const pageIndex of editedPages) {
          const pageNumber = pageIndex + 1;
          if (pageNumber > pdfDoc.numPages) continue;
          const rotation = resolvedPageRotation(pageNumber);
          const cacheKey = `${pageNumber}:${rotation}`;
          let boxes = pageTextBoxesRef.current.get(cacheKey);
          if (
            !boxes ||
            textBoxEdits.some(
              (edit) =>
                edit.page === pageIndex && /^native-text:/.test(edit.id ?? ""),
            )
          ) {
            try {
              const sourcePage = await pdfDoc.getPage(pageNumber);
              const textContent = await readPdfTextContent(sourcePage);
              const viewport = sourcePage.getViewport({ scale: 1, rotation });
              for (const [index, raw] of (Array.isArray(textContent.items)
                ? textContent.items
                : []
              ).entries()) {
                const item = nativeListTextItemEvidence(raw, index);
                const style = item
                  ? textContent.styles?.[item.fontName]
                  : undefined;
                if (
                  !item ||
                  (style && "vertical" in style && style.vertical === true)
                )
                  continue;
                const geometry = nativeTextItemLayoutGeometry(item, viewport);
                if (geometry)
                  sourceTextBoxes.push({
                    ...geometry,
                    id: `native-text:${pageNumber}:${index}:${index}`,
                    page: pageIndex,
                    text: item.str,
                  });
              }
              boxes = textBoxCommandTargetsFromPdfPageTextContent(
                sourcePage,
                textContent,
                pageIndex,
                rotation,
              );
              pageTextBoxesRef.current.set(cacheKey, boxes);
            } catch {
              boxes = [];
            }
          }
          sourceTextBoxes.push(...boxes);
        }
      }

      // Signature fields and action buttons carry no form-fill value, so they
      // are excluded from the value-flatten list. Their native action remains
      // in the document; it is not an entered field value.
      const formFieldList: FlattenFormField[] = allFormFields
        .filter(
          (f) =>
            f.type !== "signature" &&
            f.type !== "resetButton" &&
            f.type !== "printButton" &&
            f.type !== "navigationButton" &&
            f.type !== "viewButton" &&
            f.type !== "saveButton" &&
            f.type !== "goToPageButton" &&
            f.type !== "webLinkButton",
        )
        .map((f) => ({
          name: f.name,
          type: f.type as FlattenFormField["type"],
          ...(f.type === "choice" && f.multiSelect
            ? { multiSelect: true }
            : {}),
        }));

      const redactionList: FlattenRedaction[] = applyRedactions
        ? redactions.map((r) => ({
            page: r.page,
            x: r.x,
            y: r.y,
            width: r.width,
            height: r.height,
          }))
        : [];

      // What the PDF already holds -- a stamp, signature, shape, link or
      // text markup written into it and matching the reader's record -- is
      // in the source bytes: baking it again drew it twice, and hiding the
      // comments left the baked copy (user audit PDF 0011). Only the
      // reader's own objects are baked.
      const {
        shapes: exportShapes,
        signatures: exportSignatures,
        stamps: exportStamps,
        links: exportLinks,
        highlights: exportHighlights,
      } = readerOwnedExportObjects(
        { shapes, signatures, stamps, links: linkOverlays, highlights },
        {
          shapes: managedNativeShapeIdSet,
          signatures: managedNativeSignatureIdSet,
          stamps: managedNativeStampIdSet,
          links: managedNativeLinkIdSet,
        },
      );

      const shapeList: FlattenShape[] = exportShapes.map((s) => ({
        page: s.page,
        kind: s.kind,
        x1: s.x1,
        y1: s.y1,
        x2: s.x2,
        y2: s.y2,
        points: s.points,
        color: s.color,
        width: s.width,
        lineStyle: s.lineStyle,
        lineStart: s.lineStart,
        lineEnd: s.lineEnd,
        // Optional interior fill (rect / ellipse); null/undefined → outline only.
        fillColor: s.fillColor ?? null,
        fillOpacity: s.fillOpacity,
        opacity: s.opacity,
        cornerRadius: s.cornerRadius,
      }));

      // User-created hyperlinks baked as real PDF Link annotations (rect + URI or
      // GoTo). Exactly one destination per overlay (the helper enforced it).
      const linkList: FlattenLink[] = exportLinks.map((l) => ({
        page: l.page,
        x: l.x,
        y: l.y,
        width: l.width,
        height: l.height,
        url: l.url,
        goToPage: l.goToPage,
      }));

      // The exported CONTENT-page order as 1-based source pages (surviving
      // originals + duplicate slots in final sequence; blank inserts skipped).
      // Drives the stamp numbering (`pageOrder`) and sizes the label array so a
      // duplicated page still gets a running number. Identity (1..N) when there
      // are no structural edits.
      const originalPageNumbers = pages.map((p) => p.pageNumber);
      const exportOrder = exportPageOrder(pageEdits, originalPageNumbers);

      // Build the document-level decorations from the same typed model used by
      // the live preview. Source-page identity keeps custom/odd/even ranges
      // stable while the structural stage chooses final output order.
      const flattenStamp = buildExportStampConfig(
        exportOrder.length > 0 ? exportOrder : originalPageNumbers,
      );

      // Visual signatures (drawn image / typed text) baked as raster overlays.
      // Each entry mirrors the persisted `pdf_signatures` payload (already
      // sanitized on load); typed ones are rasterized by the resolver below.
      const signatureList: FlattenSignature[] = exportSignatures.map((s) => ({
        page: s.page,
        x: s.x,
        y: s.y,
        width: s.width,
        height: s.height,
        // The flatten contract has two raster paths: an uploaded-image
        // signature rides the "drawn" data-URL embed, exactly like the
        // native appearance and image stamps; only typed text rasterizes.
        kind: s.kind === "typed" ? "typed" : "drawn",
        image: s.image,
        text: s.text,
        font: s.font,
      }));

      // Rubber stamps baked like signatures: preset stamps resolve their label
      // text + color from the palette and are rasterized by the same resolver
      // (tagged `source: "stamp"`); image stamps embed their data URL directly.
      const stampAnnotationList: FlattenStampAnnotation[] = exportStamps.map((s) => {
        const preset = resolveStampPreset(s.preset);
        return {
          page: s.page,
          x: s.x,
          y: s.y,
          width: s.width,
          height: s.height,
          kind: s.kind,
          text: s.kind === "preset" && preset ? preset.text : "",
          color: s.kind === "preset" ? stampAnnotationColor(s) : "",
          image: s.image,
        };
      });

      // The flatten inputs carry geometry and colour only. An editable export
      // also needs the comment, the author and the reply thread — the very
      // things a baked highlight loses — so they ride alongside, keyed by the
      // annotation's position in the same array.
      const editableMeta = new Map<string, EditableAnnotationMeta>();
      const replyMeta = (
        replies: ReadonlyArray<PdfAnnotationReply> | undefined,
      ) =>
        (replies ?? [])
          .filter((reply) => reply.text?.trim())
          .map((reply) => ({
            name: reply.id,
            author: reply.author?.displayName,
            contents: reply.text,
          }));
      exportHighlights.forEach((h, index) => {
        editableMeta.set(`highlight:${index}`, {
          id: h.id,
          contents: h.note,
          authorName: h.author?.displayName,
          replies: replyMeta(h.replies),
        });
      });
      notes.forEach((n, index) => {
        editableMeta.set(`note:${index}`, {
          id: n.id,
          contents: n.text,
          authorName: n.author?.displayName,
          replies: replyMeta(n.replies),
        });
      });

      const annotations: FlattenAnnotations = {
        highlights: exportHighlights.map((h) => ({
          page: h.page,
          color: h.color,
          rects: h.rects,
          ...(h.quads ? { quads: h.quads } : {}),
          markupStyle: h.markupStyle,
        })),
        notes: notes.map((n) => ({
          page: n.page,
          x: n.x,
          y: n.y,
          text: n.text,
          color: n.color,
        })),
        inks: [
          ...inks.map((stroke) => ({
            page: stroke.page,
            color: stroke.color,
            
            width: inkWidthPagePercent(stroke.width, pageSizes[stroke.page - 1]),
            points: stroke.points,
          })),
          ...(nativeInkStrokes ?? [])
            .map((stroke) => nativeInkToFlattenInk(stroke, pageSizes))
            .filter((stroke): stroke is NonNullable<typeof stroke> =>
              Boolean(stroke),
            ),
        ],
        images: (nativeImageOverlays ?? [])
          .map((overlay) =>
            nativeImageOverlayToFlattenImage(overlay, pageSizes),
          )
          .filter((overlay): overlay is FlattenImage => Boolean(overlay)),
        // Non-destructive vector shapes (rect / line / arrow / ellipse) baked as
        // coloured strokes (after page markups, before redactions / stamps).
        shapes: shapeList,
        // Visual signatures baked as raster images into their placed boxes.
        signatures: signatureList,
        // Rubber stamps: same bake layer as signatures (under redactions).
        stampAnnotations: stampAnnotationList,
        // Baked as permanent OPAQUE black rectangles (drawn last, over content).
        redactions: redactionList,
        // Inline text-box edits: mask the original line + draw the edited text,
        // so the download carries the WPS-style text edits (empty -> no ops).
        textBoxes: flattenTextBoxesFromEdits(textBoxEdits, {
          pageSizes,
          sourceBoxes: sourceTextBoxes,
        }),
        // User-created hyperlinks baked as PDF Link annotations.
        links: linkList,
        // Per-page crop rectangles (去白边) baked as PDF CropBoxes (clip last, so
        // the trim wraps every baked annotation). Sanitized + de-noop'd by the
        // pure helper; an empty / full-page entry yields no crop op.
        cropBoxes: (cropBoxes ?? [])
          .map((c) => sanitizeCropBox(c as Record<string, unknown>))
          .filter((c): c is NonNullable<typeof c> => Boolean(c)),
        // Document-level watermark / page-number / Bates stamp (null when off);
        // drawn on every exported page. `pageOrder` keeps the running number
        // aligned with the FINAL page sequence after structural edits.
        stamp: flattenStamp,
        pageOrder: exportOrder,
        formValues: nativeFormMode ? {} : formValues,
        formFields: formFieldList,
      };

      // A saved file holding the page's structure (pages deleted, moved,
      // added: lib/pdf/structured-document) is the source as it is: its page
      // operations are written in it, so they are not applied again, and
      // every object baked goes on the file's page of its upload page (one on
      // a page deleted from the file is left out). The sizes are the file's.
      const exportMap = structuredDocumentMap(pdfDoc);
      // A page operation still saving is drawn over that file, not in it:
      // the file is used once it holds it.
      const heldStructure = documentPageStructureRef.current.structure;
      if (exportMap && (!heldStructure || !pageStructureIsHeld(heldStructure, pageEdits))) {
        throw Object.assign(new Error(t("pdf.viewer.pageOperationsSavingDownload")), { code: "page_structure_saving" });
      }
      const filePageOf = (page: number) => (exportMap ? documentPageForOriginal(exportMap, page) : page);
      const onFilePages = <T extends { page: number }>(list: ReadonlyArray<T> | undefined): T[] | undefined =>
        list?.flatMap((item) => {
          const page = filePageOf(item.page);
          return page === null ? [] : [{ ...item, page }];
        });
      // A page added to the file (no upload page) takes the size before it.
      let previousPageSize = pageSizes[0];
      const exportPageSizes: FlattenPageSize[] = exportMap
        ? exportMap.documentPages.map((original) => {
          if (original !== null && pageSizes[original - 1]) previousPageSize = pageSizes[original - 1];
          return previousPageSize;
        })
        : pageSizes;
      const exportAnnotations: FlattenAnnotations = exportMap
        ? {
            ...annotations,
            highlights: onFilePages(annotations.highlights),
            notes: onFilePages(annotations.notes),
            inks: onFilePages(annotations.inks),
            redactions: onFilePages(annotations.redactions),
            textBoxes: onFilePages(annotations.textBoxes),
            images: onFilePages(annotations.images),
            shapes: onFilePages(annotations.shapes),
            signatures: onFilePages(annotations.signatures),
            stampAnnotations: onFilePages(annotations.stampAnnotations),
            links: onFilePages(annotations.links)?.flatMap((link) => {
              if (link.goToPage === null || link.goToPage === undefined) return [link];
              const goToPage = filePageOf(link.goToPage);
              return goToPage === null ? [] : [{ ...link, goToPage }];
            }),
            // Written in the file with its page operations.
            cropBoxes: [],
            pageOrder: exportMap.documentPages.map((_, index) => index + 1),
          }
        : annotations;
      const exportRedactionList = exportMap ? exportAnnotations.redactions ?? [] : redactionList;

      // Redacted pages are keyed by ORIGINAL page number; the rasterization step
      // below runs on the STRUCTURALLY TRANSFORMED output, so remap each through
      // the same visible-page model the viewer renders (a deleted page maps to
      // nothing; a duplicated page rasterizes the copy too).
      const outputPagesByOriginal = exportMap
        ? new Map(exportMap.documentPages.map((_, index) => [index + 1, [index + 1]] as const))
        : mapOriginalPagesToOutput(
          pageEdits,
          originalPageNumbers,
        );
      const redactedPages = new Set<number>();
      for (const red of exportRedactionList) {
        const outputPages = outputPagesByOriginal.get(red.page);
        if (!outputPages || outputPages.length === 0) {
          throw new Error(redactionProductCopy.failure);
        }
        for (const outPage of outputPages) {
          redactedPages.add(outPage);
        }
      }
      if (applyRedactions && redactedPages.size === 0) {
        throw new Error(redactionProductCopy.failure);
      }

      // The source document's outline, resolved to ORIGINAL page numbers via the
      // live pdf.js doc (named dests / page refs only resolve there — the
      // flatten runs on pdf-lib). `flattenPdf` then remaps every entry through
      // the same pageOps output model and rebuilds /Outlines AFTER the
      // structural stage, appending the user's bookmarks as a branch, so the
      // download keeps a working TOC instead of dangling/lost bookmarks.
      const exportOutlineItems =
        pdfDoc && outline.length > 0
          ? await outlineTreeForExport(outline, {
              getDestination: (name) => pdfDoc.getDestination(name),
              getPageIndex: (ref) =>
                pdfDoc.getPageIndex(
                  ref as Parameters<typeof pdfDoc.getPageIndex>[0],
                ),
            })
          : [];

      const outlineOnFilePages = (nodes: ExportOutlineNode[]): ExportOutlineNode[] => nodes.map((node) => ({
        ...node,
        page: node.page === null ? null : filePageOf(node.page),
        children: outlineOnFilePages(node.children),
      }));
      const exportOutline = exportMap ? outlineOnFilePages(exportOutlineItems) : exportOutlineItems;
      const exportBookmarks = exportMap
        ? sortedBookmarks.flatMap((bookmark) => {
          const page = filePageOf(bookmark.page);
          return page === null ? [] : [{ ...bookmark, page }];
        })
        : sortedBookmarks;
      // Pictures only the browser can draw, for the ops the plan names.
      const { requests: flattenResourceRequests } = await planFlattenResources(
        exportAnnotations,
        exportPageSizes,
        { editableAnnotations: buildOptions.editableAnnotations === true },
      );
      const flattenResources = await drawFlattenResources(
        flattenResourceRequests,
        {
          image: resolveNativeImageOverlayBytes
            ? (op) => resolveNativeImageOverlayBytes(op.dataItemId)
            : undefined,
          formula: renderFormulaTextOpToImage,
          // Source-run text boxes keep their embedded faces as rasters.
          text: renderPdfTextOpToImage,
          // Typed signatures rasterize through the canvas path; drawn ones
          // embed their sanitized data URL directly.
          signature: renderTypedSignatureOpToImage,
        },
      );
      // Document annotations are written after any page rasterization so
      // they cannot be eaten, and before the semantic witness.
      const measurementInput: FlattenExportMeasurementsInput | undefined =
        measurements.length > 0
          ? {
              records: onFilePages(measurements) ?? measurements,
              pageSizes: exportPageSizes.map((page) => ({
                width: page.width,
                height: page.height,
              })),
            }
          : undefined;
      const { bytes: flattenedBytes } = await exportAnnotatedPdf(
        sourceBytes,
        exportAnnotations,
        exportPageSizes,
        {
          // "下载(保留可填写)": keep the AcroForm editable — values are still set
          // and the widget appearances refreshed (see lib/pdf/flatten-apply), but
          // the fields are NOT baked into static content. Default (undefined)
          // keeps the historical flatten-to-snapshot behavior.
          flattenForm: buildOptions.keepFormFillable ? false : undefined,
          // Document-info metadata edits from the properties dialog (Title /
          // Author / Subject / Keywords). Omitted -> the source PDF's existing
          // metadata is preserved (see lib/pdf/flatten-apply applyDocumentMetadata).
          metadata: buildOptions.metadata,
          // "Download with editable annotations": highlights and sticky notes
          // leave as /Annots — movable, recolourable and commentable in Acrobat
          // or WPS — instead of being painted into the page.
          editableAnnotations: buildOptions.editableAnnotations
            ? { meta: editableMeta }
            : undefined,
          // Structural page edits (rotate / delete / reorder / insert blank /
          // duplicate) bake as stage 2 after the annotation bake, so ONE download
          // carries both the content edits and the page ops. Duplicate slots ride
          // insertedPages[].copyOfPage (the legacy duplicatePages option is unused).
          pageOps: exportMap || isEmptyPageEditState(pageEdits)
            ? undefined
            : serializePageEditState(pageEdits),
          // Logical page labels (/PageLabels) when the user configured ranges.
          pageLabels: pageLabelRanges.length > 0 ? pageLabelRanges : undefined,
          // Source outline + user bookmarks, rebuilt over the final page refs.
          outline:
            exportOutline.length > 0 || exportBookmarks.length > 0
              ? {
                  items: exportOutline,
                  bookmarks: exportBookmarks.map((b) => ({
                    page: b.page,
                    label: b.label,
                  })),
                  bookmarksTitle: t("pdfViewer.outlineExportBookmarks"),
                }
              : undefined,
        },
        flattenResources,
        redactedPages.size === 0 ? measurementInput : undefined,
      );
      return rasterizeAndVerifyRedactedPdfPages(
        flattenedBytes,
        redactedPages,
        measurementInput,
      );
    },
    [
      url,
      pages,
      pageEdits,
      measurements,
      resolvedPageRotation,
      allFormFields,
      highlights,
      notes,
      inks,
      redactions,
      shapes,
      signatures,
      stamps,
      linkOverlays,
      managedNativeShapeIdSet,
      managedNativeSignatureIdSet,
      managedNativeStampIdSet,
      managedNativeLinkIdSet,
      buildExportStampConfig,
      textBoxEdits,
      cropBoxes,
      nativeInkStrokes,
      nativeImageOverlays,
      resolveNativeImageOverlayBytes,
      formValues,
      nativeFormMode,
      pageLabelRanges,
      pdfDoc,
      redactionProductCopy.blockedOutput,
      redactionProductCopy.failure,
      outline,
      sortedBookmarks,
      t,
    ],
  );

  const savePolicyEditRevisionRef = useRef<{
    builder: typeof buildAnnotatedPdfBytes;
    revision: number;
  }>({ builder: buildAnnotatedPdfBytes, revision: 1 });
  if (savePolicyEditRevisionRef.current.builder !== buildAnnotatedPdfBytes) {
    savePolicyEditRevisionRef.current = {
      builder: buildAnnotatedPdfBytes,
      revision: savePolicyEditRevisionRef.current.revision + 1,
    };
  }
  const createCurrentPdfPrintInventory = useCallback(() => {
    const sourcePages = new Map(
      pages.map((page) => [page.pageNumber, page] as const),
    );
    const sanitizedCrops = new Map<
      number,
      NonNullable<ReturnType<typeof sanitizeCropBox>>
    >();
    for (const candidate of cropBoxes ?? []) {
      const crop = sanitizeCropBox(candidate as Record<string, unknown>);
      if (crop) sanitizedCrops.set(crop.page, crop);
    }

    return createPdfPrintPageInventory(
      visiblePageItems.map((item, index): PdfPrintPageInventoryInput => {
        const sourcePageNumber =
          item.kind === "original"
            ? item.page.pageNumber
            : item.page.copyOfPage;
        const sourcePage =
          sourcePageNumber === undefined
            ? undefined
            : sourcePages.get(sourcePageNumber);
        const widthPt = sourcePage?.width ?? item.page.width;
        const heightPt = sourcePage?.height ?? item.page.height;
        const rotation = sourcePage
          ? resolvedPageRotation(sourcePage.pageNumber)
          : 0;
        const crop = sourcePage
          ? sanitizedCrops.get(sourcePage.pageNumber)
          : undefined;
        const mappedCrop = crop
          ? percentRectToUserSpace(crop, {
              width: widthPt,
              height: heightPt,
              rotation,
            })
          : null;
        if (crop && !mappedCrop) {
          throw new Error("Invalid PDF print crop inventory");
        }
        return {
          page: index + 1,
          widthPt: mappedCrop?.width ?? widthPt,
          heightPt: mappedCrop?.height ?? heightPt,
          rotation,
        };
      }),
    );
  }, [cropBoxes, pages, resolvedPageRotation, visiblePageItems]);
  const createCurrentPdfPrintInventoryRef = useRef(
    createCurrentPdfPrintInventory,
  );
  useLayoutEffect(() => {
    createCurrentPdfPrintInventoryRef.current = createCurrentPdfPrintInventory;
  }, [createCurrentPdfPrintInventory]);

  const printPreflightReceiptIsCurrent = useCallback(
    (receipt: PendingPdfPrintPreflight): boolean => {
      const loaded = loadedPdfSourceIdentityRef.current;
      const source = savePolicyRuntimeRef.current.source;
      const retained = retainedPdfPrintSourceBytesRef.current;
      if (
        !loaded ||
        !source ||
        !retained ||
        loaded.document !== receipt.document ||
        loaded.dataItemId !== receipt.dataItemId ||
        loaded.url !== receipt.url ||
        loaded.byteGenerationKey !== receipt.byteGenerationKey ||
        source.identity.dataItemId !== receipt.dataItemId ||
        source.identity.byteGenerationKey !== receipt.byteGenerationKey ||
        source.identity.documentRevision !== receipt.documentRevision ||
        source.identity.sha256 !== receipt.sourceSha256 ||
        retained.document !== receipt.document ||
        retained.dataItemId !== receipt.dataItemId ||
        retained.url !== receipt.url ||
        retained.byteGenerationKey !== receipt.byteGenerationKey ||
        retained.documentRevision !== receipt.documentRevision ||
        retained.sha256 !== receipt.sourceSha256 ||
        sourceDocumentRevisionRef.current !== receipt.documentRevision ||
        savePolicyRuntimeRef.current.documentAuthority !==
          receipt.documentAuthority ||
        // The edit revision follows the annotated-bytes builder, which is
        // rebuilt whenever its inputs get new identities, also while pages
        // are still rendering (native ink, form values) with nothing edited.
        // A print without edits sends the verified source bytes and never
        // calls the builder, so that churn cannot change what prints: the
        // receipt only goes stale if an output edit has appeared since.
        ((receipt.hasEdits || hasEffectivePdfOutputEditsRef.current) &&
          savePolicyEditRevisionRef.current.revision !== receipt.editRevision) ||
        !revalidateVisualMaskOutputAuthority(receipt.outputAuthority, "print")
      ) {
        return false;
      }
      try {
        const matches = pdfPrintPageInventoriesMatch(
          receipt.inventory,
          createCurrentPdfPrintInventoryRef.current(),
        );
        if (!matches) setFlattenError(t("pdfViewer.flattenFailed"));
        return matches;
      } catch {
        setFlattenError(t("pdfViewer.flattenFailed"));
        return false;
      }
    },
    [revalidateVisualMaskOutputAuthority, t],
  );

  const readVerifiedPrintSourceBytes = useCallback(
    async (receipt: PendingPdfPrintPreflight): Promise<Uint8Array | null> => {
      if (!printPreflightReceiptIsCurrent(receipt)) return null;
      const retained = retainedPdfPrintSourceBytesRef.current;
      if (
        !retained ||
        retained.document !== receipt.document ||
        retained.dataItemId !== receipt.dataItemId ||
        retained.url !== receipt.url ||
        retained.byteGenerationKey !== receipt.byteGenerationKey ||
        retained.documentRevision !== receipt.documentRevision ||
        retained.sha256 !== receipt.sourceSha256
      ) {
        return null;
      }
      const bytes = new Uint8Array(retained.bytes.byteLength);
      bytes.set(retained.bytes);
      if (!printPreflightReceiptIsCurrent(receipt)) {
        bytes.fill(0);
        return null;
      }
      const inspected = await inspectPdfSourceRiskSnapshot({
        dataItemId: receipt.dataItemId,
        byteGenerationKey: receipt.byteGenerationKey,
        bytes,
        documentRevision: receipt.documentRevision,
      });
      if (
        !printPreflightReceiptIsCurrent(receipt) ||
        inspected.identity.sha256 !== receipt.sourceSha256
      ) {
        bytes.fill(0);
        return null;
      }
      return bytes;
    },
    [printPreflightReceiptIsCurrent],
  );

  const cancelPrintPreflight = useCallback(() => {
    pendingPrintPreflightRef.current = null;
    setPendingPrintPreflight(null);
  }, []);

  const createReaderSavePolicyRequest = useCallback(
    (options: {
      action: PdfSavePolicyAction;
      disposition: "native" | "read-only" | "flatten-with-consent";
      hasEdits: boolean;
      lossReport?: PdfOutputLossReport;
      optionRevision?: string;
      pagePackage?: PdfPagePackagePolicyContext;
      deskewRaster?: PdfDeskewRasterPolicyContext;
      lossyCompression?: PdfLossyCompressionPolicyContext;
      source?: PdfSourceRiskSnapshot | null;
      editable?: boolean;
    }): PdfSavePolicyRequest => ({
      host: "reader",
      action: options.action,
      requestedDisposition: options.disposition,
      documentReady: savePolicyRuntimeRef.current.documentReady,
      editable:
        options.editable === undefined
          ? savePolicyRuntimeRef.current.editable
          : options.editable,
      source:
        options.source === undefined
          ? savePolicyRuntimeRef.current.source
          : options.source,
      pagePackage: options.pagePackage,
      deskewRaster: options.deskewRaster,
      lossyCompression: options.lossyCompression,
      edit: createPdfSavePolicyEditSnapshot({
        editRevision: options.optionRevision
          ? `${savePolicyEditRevisionRef.current.revision}:${options.optionRevision}`
          : savePolicyEditRevisionRef.current.revision,
        hasEdits: options.hasEdits,
        lossReport:
          options.disposition === "native"
            ? (options.lossReport ?? createPdfOutputLossReport([]))
            : withVisualMaskOutputLoss(
                options.action,
                options.lossReport ??
                  createPdfOutputLossReportForAction(options.action),
              ),
      }),
    }),
    [withVisualMaskOutputLoss],
  );
  const resolveReaderSavePolicy = useCallback(
    (request: PdfSavePolicyRequest) => {
      const decision = resolvePdfSavePolicy(request);
      return {
        request,
        decision,
        view: readPdfSavePolicyDecision(decision),
      };
    },
    [],
  );

  // "Download with annotations": bake the annotations and trigger a local save.
  // `keepFormFillable` is the secondary "下载(保留可填写)" mode: the AcroForm
  // survives in the output (values set, appearances refreshed, fields editable).
  // `metadata` carries properties-dialog edits into the bake. Returns whether
  // the download actually happened (the dialog keeps itself open on failure).
  const rememberFileOpResult = useCallback(
    (bytes: Uint8Array, name: string) => {
      const copy = new Uint8Array(bytes.byteLength);
      copy.set(bytes);
      const result = { bytes: copy, name };
      // Publish the exact offer to the synchronous authority before scheduling
      // React state. An older in-flight import can then never consume a newer
      // result that arrived while its durable ImportBatch was pending.
      fileOpResultRef.current?.bytes.fill(0);
      fileOpResultRef.current = result;
      setFileOpResult(result);
      setFileOpSaved(null);
    },
    [],
  );

  const handleDownloadWithAnnotations = useCallback(
    async (
      downloadOptions: {
        keepFormFillable?: boolean;
        metadata?: PdfMetadata;
        editableAnnotations?: boolean;
        applyRedactions?: boolean;
        policyAction?: PdfSavePolicyAction;
      } = {},
    ): Promise<boolean> => {
      if (loadingNowRef.current && !(await waitForShownRevision())) return false;
      if (!annotatedDownloadEnabled || flattening) return false;
      const applyRedactions = downloadOptions.applyRedactions === true;
      const action: PdfSavePolicyAction =
        downloadOptions.policyAction ??
        (downloadOptions.editableAnnotations === true
          ? "download-editable-annotations"
          : downloadOptions.keepFormFillable === true
            ? "download-fillable"
            : downloadOptions.metadata
              ? "download-properties"
              : "download-annotated");
      if (
        matchedSourceRiskSnapshot &&
        matchedSourceRiskSnapshot.profile.xfa !== "none"
      ) {
        setFlattenError(xfaBlockedReason);
        return false;
      }
      if ((action === "pdf.redaction.apply") !== applyRedactions) {
        setFlattenError(redactionProductCopy.failure);
        return false;
      }
      if (redactionOutputRiskPresentRef.current && !applyRedactions) {
        setFlattenError(redactionProductCopy.blockedOutput);
        return false;
      }
      if (blockVisualMaskDerivedPdfOutput(action)) return false;
      const liveRedactionHydration = redactionHydrationAuthorityRef.current;
      const liveRedactionMutation = redactionMutationAuthorityRef.current;
      if (
        applyRedactions &&
        (!savePolicyV1 ||
          liveRedactionHydration.documentIdentity !==
            liveRedactionMutation.documentIdentity ||
          liveRedactionHydration.status !== "ready" ||
          liveRedactionMutation.writesInFlight > 0 ||
          redactions.length === 0 ||
          !pdfRedactionReachabilityV2Enabled())
      ) {
        setFlattenError(redactionProductCopy.failure);
        return false;
      }
      const lossReport = createPdfOutputLossReportForAction(action);
      const optionRevision = applyRedactions
        ? `redaction-marks:${redactions.length}`
        : downloadOptions.metadata
          ? JSON.stringify(downloadOptions.metadata)
          : undefined;
      const policyRequest = createReaderSavePolicyRequest({
        action,
        disposition: "flatten-with-consent",
        hasEdits: true,
        lossReport,
        optionRevision,
      });
      const policy = savePolicyV1
        ? resolveReaderSavePolicy(policyRequest)
        : null;
      if (policy && (!policy.view || !policy.view.enabled)) {
        setFlattenError(
          policy.view?.reasonKey ?? t("pdf.viewer.notice.outputBlockedByPolicy"),
        );
        return false;
      }
      const consentReceipt =
        policy?.view?.requiresConsent === true
          ? await requestOutputConsent(policyRequest, policy.decision)
          : null;
      if (policy?.view?.requiresConsent === true && !consentReceipt) {
        return false;
      }
      // The rollback path has no consent authority for rewriting certificate-
      // signed or unclassified bytes. Only an exact source inspection of
      // `none` can make this document rewrite-safe; proof status is read-only.
      if (!savePolicyV1) {
        if (
          matchedSourceRiskSnapshot?.profile.certificateSignatures !== "none"
        ) {
          setSignatureWarning(
            t("pdf.viewer.notice.editedExportSignedSource"),
          );
          return false;
        }
      }
      const keepFormFillable = downloadOptions.keepFormFillable === true;
      const editableAnnotations = downloadOptions.editableAnnotations === true;
      // This attempt replaces the last one's outcome: its "downloaded" and
      // its "save to notebook" must not stand beside this attempt's failure.
      beginOutputAttempt();
      setFlattening(true);
      try {
        if (
          policy &&
          (!consentReceipt ||
            !consumePdfSavePolicyConsentReceipt({
              receipt: consentReceipt,
              documentAuthority: savePolicyRuntimeRef.current.documentAuthority,
              decision: policy.decision,
              currentRequest: createReaderSavePolicyRequest({
                action,
                disposition: "flatten-with-consent",
                hasEdits: true,
                lossReport,
                optionRevision,
              }),
            }))
        ) {
          if (applyRedactions) {
            setFlattenError(redactionProductCopy.failure);
          }
          return false;
        }
        const outputAuthorityFailure = applyRedactions
          ? redactionProductCopy.failure
          : undefined;
        const outputAuthorityIsCurrent =
          createVisualMaskOutputAuthorityGuard(
          action,
          outputAuthorityFailure,
        );
        if (!outputAuthorityIsCurrent) return false;
        const outBytes = await buildAnnotatedPdfBytes({
          keepFormFillable,
          metadata: downloadOptions.metadata,
          editableAnnotations,
          applyRedactions,
        });
        if (!outputAuthorityIsCurrent()) return false;
        // Copy into a fresh ArrayBuffer-backed view so the Blob never references a
        // SharedArrayBuffer / detached buffer (TS BlobPart compatibility too).
        const blobBytes = new Uint8Array(outBytes.byteLength);
        blobBytes.set(outBytes);
        if (!outputAuthorityIsCurrent()) return false;
        const blob = new Blob([blobBytes], { type: "application/pdf" });
        if (!outputAuthorityIsCurrent()) return false;
        const base = (filename || "document.pdf").replace(/\.pdf$/i, "");
        const downloadName = `${base}-${
          applyRedactions
            ? "redacted"
            : editableAnnotations
              ? "commented"
              : keepFormFillable
                ? "fillable"
                : "annotated"
        }.pdf`;
        if (!outputAuthorityIsCurrent()) return false;
        // The shared Blob download keeps the object URL alive through
        // WebKit's download task (revoked on the next tick, an iPad dropped
        // a large file), and a file built after the click stopped counting
        // as one gets the shell's Save offer -- which hands over these same
        // bytes only while their output authority still stands.
        if (!startDownloadWhenAllowed(downloadName, () =>
          outputAuthorityIsCurrent() && downloadBlobFile(downloadName, blob))) {
          throw new Error("download_unavailable");
        }
        if (!outputAuthorityIsCurrent()) return false;
        rememberFileOpResult(blobBytes, downloadName);
        if (applyRedactions) setPdfActionNotice(redactionProductCopy.success, "status");
        return true;
      } catch (error) {
        // What failed inside (a builder, an encoder, the browser's download)
        // is not the reader's vocabulary; the result is -- unless the reader
        // can act on it (the export service's font is missing).
        const exportFailureKey = pdfExportFailureMessageKey(error);
        // Development: what the builder refused (an annotated download that
        
        if (process.env.NODE_ENV !== "production") {
          console.warn("[pdf-download] annotated PDF not built", {
            keepFormFillable, editableAnnotations, applyRedactions,
            error: error instanceof Error ? `${error.name}: ${error.message}` : String(error),
          });
        }
        setFlattenError(
          exportFailureKey
            ? t(exportFailureKey)
            : applyRedactions
              ? redactionProductCopy.failure
              : t("pdf.viewer.pdfDownloadFailed"),
        );
        return false;
      } finally {
        setFlattening(false);
      }
    },
    [
      beginOutputAttempt,
      annotatedDownloadEnabled,
      blockVisualMaskDerivedPdfOutput,
      createVisualMaskOutputAuthorityGuard,
      createReaderSavePolicyRequest,
      flattening,
      loading,
      matchedSourceRiskSnapshot,
      buildAnnotatedPdfBytes,
      filename,
      rememberFileOpResult,
      redactionProductCopy.blockedOutput,
      redactionProductCopy.failure,
      redactionProductCopy.success,
      redactions.length,
      requestOutputConsent,
      resolveReaderSavePolicy,
      savePolicyV1,
      t,
      xfaBlockedReason,
    ],
  );

  const handleDownloadFillable = useCallback(
    () => handleDownloadWithAnnotations({ keepFormFillable: true }),
    [handleDownloadWithAnnotations],
  );
  const handleDownloadEditableAnnotations = useCallback(
    () => handleDownloadWithAnnotations({ editableAnnotations: true }),
    [handleDownloadWithAnnotations],
  );
  const cancelVerifiedPdfaExport = useCallback(() => {
    verifiedPdfaExportSessionGenerationRef.current += 1;
    verifiedPdfaExportAbortRef.current?.abort();
    verifiedPdfaExportAbortRef.current = null;
    verifiedPdfaExportInFlightRef.current = false;
    setVerifiedPdfaExportBusy(false);
    setVerifiedPdfaExportError(null);
    setVerifiedPdfaExportOpen(false);
  }, []);
  useEffect(() => {
    cancelVerifiedPdfaExport();
  }, [
    cancelVerifiedPdfaExport,
    expectedSourceByteGenerationKey,
    matchedSourceRiskSnapshot?.identity.sha256,
    url,
  ]);
  const handleDownloadArchival = useCallback((): boolean => {
    if (verifiedPdfaExportInFlightRef.current) return false;
    const requestedDocument = pdfDocRef.current;
    const requestedLoadedSource = loadedPdfSourceIdentityRef.current;
    const requestedSource = matchedSourceRiskSnapshot;
    const requestedPageItems = visiblePageItemsRef.current;
    const requestedPages = pagesRef.current;
    const requestedGeneration =
      verifiedPdfaExportSessionGenerationRef.current + 1;
    verifiedPdfaExportSessionGenerationRef.current = requestedGeneration;
    verifiedPdfaExportAbortRef.current?.abort();
    setVerifiedPdfaCapability(null);
    setVerifiedPdfaExportError(null);
    setVerifiedPdfaExportOpen(true);
    setVerifiedPdfaExportAvailability("checking");

    const setUnavailable = (reason: string) => {
      if (
        verifiedPdfaExportSessionGenerationRef.current === requestedGeneration
      ) {
        setVerifiedPdfaExportAvailability("unavailable");
        setVerifiedPdfaExportError(null);
        setVerifiedPdfaCapability(
          requestedSource && requestedDocument
            ? Object.freeze({
                sourceSha256: requestedSource.identity.sha256,
                pageCount: requestedDocument.numPages,
                profile: "2b" as const,
                eligible: false,
                disabledReason: reason,
                converter: null,
                verifier: null,
              })
            : null,
        );
      }
    };
    if (
      !savePolicyV1 ||
      !pdfSavePolicyV1Enabled() ||
      !dataItemId ||
      !requestedDocument ||
      !requestedLoadedSource ||
      !requestedSource ||
      requestedLoadedSource.document !== requestedDocument ||
      requestedLoadedSource.dataItemId !== dataItemId ||
      requestedLoadedSource.url !== url ||
      requestedLoadedSource.byteGenerationKey !==
        expectedSourceByteGenerationKey ||
      requestedSource.identity.dataItemId !== dataItemId ||
      !/^[0-9a-f]{64}$/.test(requestedSource.identity.sha256) ||
      requestedPages.length !== requestedDocument.numPages ||
      requestedPageItems.length !== requestedDocument.numPages ||
      requestedPageItems.some(
        (item, index) =>
          item.kind !== "original" || item.page.pageNumber !== index + 1,
      )
    ) {
      setUnavailable(
        t("pdf.viewer.authenticatedOriginalPdfAuthorityUnavailable"),
      );
      return true;
    }
    if (
      requestedSource.profile.encryption !== "none" ||
      requestedSource.profile.certificateSignatures !== "none"
    ) {
      setUnavailable(
        t("pdf.viewer.encryptedSignedPdfsCannotConverted"),
      );
      return true;
    }
    if (
      hasEffectivePdfOutputEditsRef.current ||
      formValueEditorEditsRef.current
    ) {
      setUnavailable(
        t("pdf.viewer.saveCurrentEditsFirstPdf"),
      );
      return true;
    }

    const authorityIsCurrent = (): boolean =>
      verifiedPdfaExportSessionGenerationRef.current === requestedGeneration &&
      pdfDocRef.current === requestedDocument &&
      loadedPdfSourceIdentityRef.current === requestedLoadedSource &&
      savePolicyRuntimeRef.current.source === requestedSource &&
      sourceDocumentRevisionRef.current ===
        requestedSource.identity.documentRevision &&
      visiblePageItemsRef.current === requestedPageItems &&
      pagesRef.current === requestedPages &&
      !hasEffectivePdfOutputEditsRef.current &&
      !formValueEditorEditsRef.current;
    const controller = new AbortController();
    verifiedPdfaExportAbortRef.current = controller;
    const query = new URLSearchParams({
      source_sha256: requestedSource.identity.sha256,
      page_count: String(requestedDocument.numPages),
      profile: "2b",
    });
    void apiGet<unknown>(
      `/api/v1/data-items/${encodeURIComponent(
        dataItemId,
      )}/verified-pdfa-export?${query.toString()}`,
      { signal: controller.signal },
    )
      .then((value) => {
        if (!authorityIsCurrent() || controller.signal.aborted) return;
        const capability = parsePdfVerifiedPdfaCapability(
          value,
          requestedSource.identity.sha256,
          requestedDocument.numPages,
        );
        if (!capability) throw new Error("Invalid PDF/A capability response");
        setVerifiedPdfaCapability(capability);
        setVerifiedPdfaExportAvailability(
          capability.eligible ? "available" : "unavailable",
        );
      })
      .catch((error) => {
        if (controller.signal.aborted || !authorityIsCurrent()) return;
        setVerifiedPdfaExportAvailability("error");
        setVerifiedPdfaExportError(
          t("pdf.viewer.productionPdfConversionServiceCould"),
        );
        if (error instanceof DOMException && error.name === "AbortError")
          return;
      })
      .finally(() => {
        if (verifiedPdfaExportAbortRef.current === controller) {
          verifiedPdfaExportAbortRef.current = null;
        }
      });
    return true;
  }, [
    dataItemId,
    expectedSourceByteGenerationKey,
    t,
    matchedSourceRiskSnapshot,
    savePolicyV1,
    url,
  ]);
  const handleCreateVerifiedPdfaExport = useCallback(async () => {
    if (verifiedPdfaExportInFlightRef.current) return;
    const requestedCapability = verifiedPdfaCapability;
    const requestedDocument = pdfDocRef.current;
    const requestedLoadedSource = loadedPdfSourceIdentityRef.current;
    const requestedSource = matchedSourceRiskSnapshot;
    const requestedPageItems = visiblePageItemsRef.current;
    const requestedPages = pagesRef.current;
    const requestedGeneration = verifiedPdfaExportSessionGenerationRef.current;
    if (
      !dataItemId ||
      !requestedCapability?.eligible ||
      !requestedDocument ||
      !requestedLoadedSource ||
      !requestedSource ||
      requestedCapability.sourceSha256 !== requestedSource.identity.sha256 ||
      requestedCapability.pageCount !== requestedDocument.numPages ||
      requestedLoadedSource.document !== requestedDocument ||
      requestedLoadedSource.dataItemId !== dataItemId ||
      requestedSource.identity.dataItemId !== dataItemId ||
      hasEffectivePdfOutputEditsRef.current ||
      formValueEditorEditsRef.current
    ) {
      setVerifiedPdfaExportError(
        t("pdf.viewer.currentPdfAuthorityChangedNo"),
      );
      return;
    }
    const authorityIsCurrent = (): boolean =>
      verifiedPdfaExportSessionGenerationRef.current === requestedGeneration &&
      verifiedPdfaCapability === requestedCapability &&
      pdfDocRef.current === requestedDocument &&
      loadedPdfSourceIdentityRef.current === requestedLoadedSource &&
      savePolicyRuntimeRef.current.source === requestedSource &&
      sourceDocumentRevisionRef.current ===
        requestedSource.identity.documentRevision &&
      visiblePageItemsRef.current === requestedPageItems &&
      pagesRef.current === requestedPages &&
      !hasEffectivePdfOutputEditsRef.current &&
      !formValueEditorEditsRef.current;

    const controller = new AbortController();
    verifiedPdfaExportAbortRef.current?.abort();
    verifiedPdfaExportAbortRef.current = controller;
    verifiedPdfaExportInFlightRef.current = true;
    beginOutputAttempt();
    setVerifiedPdfaExportBusy(true);
    setVerifiedPdfaExportError(null);
    let output: Uint8Array | null = null;
    try {
      if (!authorityIsCurrent()) return;
      const response = await apiFetchRaw(
        `/api/v1/data-items/${encodeURIComponent(
          dataItemId,
        )}/verified-pdfa-export`,
        {
          method: "POST",
          signal: controller.signal,
          body: JSON.stringify({
            source_sha256: requestedSource.identity.sha256,
            page_count: requestedDocument.numPages,
            profile: "2b",
            confirm_create_copy: true,
          }),
        },
        { contentType: "application/json" },
      );
      if (!authorityIsCurrent()) return;
      const outputSha256 = response.headers.get("x-pdfa-output-sha256");
      const responsePageCount = Number.parseInt(
        response.headers.get("x-pdfa-page-count") ?? "",
        10,
      );
      const responseMediaType =
        response.headers.get("content-type")?.split(";", 1)[0].trim() ?? "";
      if (
        response.headers.get("x-pdf-source-sha256") !==
          requestedSource.identity.sha256 ||
        response.headers.get("x-pdfa-profile") !== "2b" ||
        response.headers.get("x-pdfa-verifier") !== "veraPDF 1.30.2" ||
        !response.headers
          .get("x-pdfa-converter")
          ?.startsWith("Ghostscript 10.") ||
        !outputSha256 ||
        !/^[0-9a-f]{64}$/.test(outputSha256) ||
        responsePageCount !== requestedDocument.numPages ||
        responseMediaType !== "application/pdf"
      ) {
        throw new Error("Invalid verified PDF/A response authority");
      }
      const responseBuffer = await response.arrayBuffer();
      output = new Uint8Array(responseBuffer);
      if (
        !authorityIsCurrent() ||
        new TextDecoder("ascii").decode(output.subarray(0, 5)) !== "%PDF-" ||
        (await pdfBytesSha256(output)) !== outputSha256 ||
        !(await verifyPdfaClientReopen(output, requestedDocument.numPages))
      ) {
        throw new Error("Verified PDF/A failed client reopen authority");
      }
      if (!authorityIsCurrent()) return;
      const blob = new Blob([responseBuffer], { type: "application/pdf" });
      if (!downloadBlobFile(`${annotationExportBase}-pdfa-2b.pdf`, blob)) {
        throw new Error("PDF/A download is unavailable");
      }
      setVerifiedPdfaExportOpen(false);
    } catch (error) {
      if (
        verifiedPdfaExportSessionGenerationRef.current ===
          requestedGeneration &&
        !(error instanceof DOMException && error.name === "AbortError")
      ) {
        setVerifiedPdfaExportError(
          t("pdf.viewer.pdfBDidNotPass"),
        );
      }
    } finally {
      output?.fill(0);
      if (
        verifiedPdfaExportSessionGenerationRef.current ===
          requestedGeneration &&
        verifiedPdfaExportAbortRef.current === controller
      ) {
        verifiedPdfaExportAbortRef.current = null;
        verifiedPdfaExportInFlightRef.current = false;
        setVerifiedPdfaExportBusy(false);
      }
    }
  }, [
    beginOutputAttempt,
    annotationExportBase,
    dataItemId,
    t,
    matchedSourceRiskSnapshot,
    verifiedPdfaCapability,
  ]);
  const handleApplyRedactions = useCallback(
    () =>
      handleDownloadWithAnnotations({
        applyRedactions: true,
        policyAction: "pdf.redaction.apply",
      }),
    [handleDownloadWithAnnotations],
  );

  useEffect(() => {
    const requestId = downloadWithAnnotationsRequestId ?? 0;
    if (
      requestId <= 0 ||
      requestId === lastExternalAnnotatedDownloadRequestRef.current
    ) {
      return;
    }
    lastExternalAnnotatedDownloadRequestRef.current = requestId;
    if (loading || !annotatedDownloadEnabled) {
      onDownloadWithAnnotationsSettled?.(requestId, false);
      return;
    }
    externalAnnotatedDownloadInFlightRef.current = requestId;
    const settle = (succeeded: boolean) => {
      if (externalAnnotatedDownloadInFlightRef.current === requestId) {
        externalAnnotatedDownloadInFlightRef.current = null;
      }
      onDownloadWithAnnotationsSettled?.(requestId, succeeded);
    };
    void handleDownloadWithAnnotations({
      policyAction: downloadWithAnnotationsPolicyAction,
    })
      .then(settle)
      .catch(() => settle(false));
  }, [
    annotatedDownloadEnabled,
    downloadWithAnnotationsRequestId,
    downloadWithAnnotationsPolicyAction,
    handleDownloadWithAnnotations,
    loading,
    onDownloadWithAnnotationsSettled,
  ]);

  /**
   * Commit one preflight-proved form-data operation through the existing
   * generation-bound native form FIFO. CSV/XFDF parsing never crosses this
   * boundary: only exact typed field values do. The whole import/reset is one
   * closed gesture, so the host publishes one lossless receipt and one Undo
   * entry even when calculation fields also change.
   */
  const executeNativeFormValuePlan = useCallback(
    async (options: {
      readonly invocation: PdfCommandInvocation;
      readonly action: "pdf.form.reset-values" | "pdf.form.import-data";
      readonly planDigest: string;
      readonly operationGeneration: number;
      readonly source: PdfSourceRiskSnapshot;
      readonly updates: readonly PdfFormNativeValueUpdate[];
    }): Promise<boolean> => {
      const authorityAtStart = nativeFormWriteAuthorityRef.current;
      if (
        !authorityAtStart?.writable ||
        !nativeFormFieldChangeRef.current ||
        options.updates.length === 0
      ) {
        return false;
      }
      const expectedGeneration = authorityAtStart.generation;
      const optionRevision = () =>
        `native-form-values:${options.planDigest}:${formValueOutputGenerationRef.current}:${nativeFormWriteAuthorityRef.current?.generation ?? "missing"}`;
      const requestFor = (
        source: PdfSourceRiskSnapshot | null | undefined,
      ): PdfSavePolicyRequest =>
        createReaderSavePolicyRequest({
          action: options.action,
          disposition: "native",
          editable:
            nativeFormWriteAuthorityRef.current?.writable === true &&
            typeof nativeFormFieldChangeRef.current === "function",
          hasEdits: true,
          lossReport: createPdfOutputLossReport([]),
          optionRevision: optionRevision(),
          source,
        });
      const request = requestFor(options.source);
      const policy = resolveReaderSavePolicy(request);
      const view = policy.view;
      if (!view?.enabled || view.disposition !== "native") return false;
      const currentRequest = () =>
        requestFor(savePolicyRuntimeRef.current.source);
      if (!verifyPdfSavePolicyDecision(policy.decision, currentRequest())) {
        return false;
      }

      const operationOwner = createPdfCommandAuthorityOwner({
        host: "reader",
        instanceId: `${commandInstanceId}:native-form-values:${options.operationGeneration}`,
        invocation: options.invocation,
      });
      const authority = operationOwner.bind(async () => {
        const isCurrent = () =>
          formValueOutputGenerationRef.current ===
            options.operationGeneration &&
          nativeFormWriteAuthorityRef.current?.writable === true &&
          nativeFormWriteAuthorityRef.current.generation ===
            expectedGeneration &&
          typeof nativeFormFieldChangeRef.current === "function" &&
          verifyPdfSavePolicyDecision(policy.decision, currentRequest());
        if (!isCurrent()) return false;
        if (
          !(await flushFormValues({ includeOpenNativeGesture: true })) ||
          !isCurrent()
        ) {
          return false;
        }

        const previousLocal = { ...formValuesRef.current };
        const before = { ...sourceFormValues, ...previousLocal };
        const next = { ...previousLocal };
        for (const update of options.updates) {
          setFormValueEntry(
            next,
            update.name,
            typeof update.value === "string" ||
              typeof update.value === "boolean"
              ? update.value
              : [...update.value],
          );
        }

        const scripted = allFormFields
          .filter((field) => field.calculateScript || field.formatScript)
          .map((field) => ({
            name: field.name,
            calculate: field.calculateScript ?? undefined,
            format: field.formatScript ?? undefined,
          }));
        // A read-only calculated field is the document's own output: it shows
        // the value its calculation gives, and the server writes that value
        // from the same script when it applies this transaction. It is never
        // sent as a direct write, which /Ff ReadOnly rightly refuses.
        const derivedNames = new Set<string>();
        if (scripted.length > 0) {
          const { values: computed } = recalculateFields(
            scripted,
            calculationInputValues(allFormFields, { ...sourceFormValues, ...next }),
            calculationOrderRef.current,
            locale,
            allFormFields.map((field) => field.name),
          );
          const known = new Map(allFormFields.map((field) => [field.name, field]));
          for (const [name, value] of computed) {
            const computedField = known.get(name);
            if (!computedField) continue;
            setFormValueEntry(next, name, String(value));
            if (computedField.readOnly) derivedNames.add(name);
          }
        }

        const changedNames = Object.keys(next).filter(
          (name) =>
            !derivedNames.has(name) &&
            !acroFormValuesEqual(before[name], next[name]),
        );
        if (changedNames.length === 0) return true;
        if (!isCurrent()) return false;

        const gestureId = `${expectedGeneration}:${++nativeFormGestureSequenceRef.current}:${options.action}`;
        const gesture: PendingNativeFormGesture = {
          id: gestureId,
          generation: expectedGeneration,
          fields: new Map(
            changedNames.map((name) => [
              name,
              {
                id: name,
                value: next[name]!,
                label: name,
              },
            ]),
          ),
          previous: new Map(
            changedNames
              .filter((name) => before[name] !== undefined)
              .map((name) => [name, { id: name, value: before[name]!, label: name }]),
          ),
          closed: true,
        };
        pendingNativeFormGesturesRef.current.push(gesture);
        for (const name of changedNames) formTouchedRef.current.add(name);
        formValuesRef.current = next;
        setFormValues(next);
        publishNativeFormPending();

        const accepted = await flushFormValues();
        // Acknowledged by the host = written. The revision that write
        // publishes moves the source and the edit revision, so re-checking
        // the pre-write decision here reported every successful import or
        
        if (accepted) return true;

        pendingNativeFormGesturesRef.current =
          pendingNativeFormGesturesRef.current.filter(
            (candidate) => candidate !== gesture,
          );
        formValuesRef.current = previousLocal;
        setFormValues(previousLocal);
        publishNativeFormPending();
        return false;
      });
      const runtime = {
        featureFlags: readPdfFeatureFlagState(),
        decisions: {
          [options.invocation.featureId]: {
            enabled: true,
            disposition: "native",
            savePolicy: { request, decision: policy.decision },
          },
        },
      } satisfies PdfFeatureRuntimeState;
      const context: PdfCapabilityContext = {
        host: "reader",
        documentReady: savePolicyRuntimeRef.current.documentReady,
        editable: authorityAtStart.writable,
      };
      return (
        (await authority.execute(options.invocation, context, runtime)) ===
        "executed"
      );
    },
    [
      allFormFields,
      commandInstanceId,
      createReaderSavePolicyRequest,
      flushFormValues,
      locale,
      publishNativeFormPending,
      resolveReaderSavePolicy,
      sourceFormValues,
    ],
  );

  const executeLosslessCompressionOutput = useCallback(
    async (options: {
      readonly request: PdfSavePolicyRequest;
      readonly decision: PdfSavePolicyDecision;
      readonly lossReport: PdfOutputLossReport;
      readonly result: Awaited<ReturnType<PdfDocumentWriters["compressPdfWithStats"]>>;
      readonly outputName: string;
      readonly operationGeneration: number;
      readonly outputAuthorityIsCurrent: () => boolean;
    }): Promise<boolean> => {
      const view = readPdfSavePolicyDecision(options.decision);
      if (!view?.enabled) return false;
      const currentRequest = () =>
        createReaderSavePolicyRequest({
          action: "pdf.file.compress-lossless",
          disposition: "flatten-with-consent",
          hasEdits: true,
          lossReport: options.lossReport,
          optionRevision: `compress:${compressPresetRuntimeRef.current}`,
        });
      const isCurrent = () =>
        compressionHostMountedRef.current &&
        losslessCompressionGenerationRef.current ===
          options.operationGeneration &&
        compressPresetRuntimeRef.current === PDF_COMPRESS_LOSSLESS_PRESET &&
        options.outputAuthorityIsCurrent() &&
        verifyPdfSavePolicyDecision(options.decision, currentRequest());
      if (!isCurrent()) return false;
      const operationOwner = createPdfCommandAuthorityOwner({
        host: "reader",
        instanceId: `${commandInstanceId}:lossless-compress:${options.operationGeneration}`,
        invocation: PDF_READER_COMPRESS_LOSSLESS_COMMAND,
      });
      const authority = operationOwner.bind(async () => {
        if (!isCurrent()) return false;
        const receipt = await requestOutputConsent(
          options.request,
          options.decision,
        );
        if (!receipt || !isCurrent()) return false;
        const exactCurrentRequest = currentRequest();
        if (
          !consumePdfSavePolicyConsentReceipt({
            receipt,
            documentAuthority: savePolicyRuntimeRef.current.documentAuthority,
            decision: options.decision,
            currentRequest: exactCurrentRequest,
          }) ||
          !isCurrent()
        ) {
          return false;
        }

        const blobBytes = new Uint8Array(options.result.bytes.byteLength);
        blobBytes.set(options.result.bytes);
        if (!isCurrent()) {
          blobBytes.fill(0);
          return false;
        }
        const objectUrl = URL.createObjectURL(
          new Blob([blobBytes], { type: "application/pdf" }),
        );
        try {
          const link = document.createElement("a");
          link.href = objectUrl;
          link.download = options.outputName;
          document.body.appendChild(link);
          if (!isCurrent()) {
            link.remove();
            return false;
          }
          link.click();
          link.remove();
          if (!isCurrent()) return false;
          rememberFileOpResult(blobBytes, options.outputName);
          if (!isCurrent()) return false;
          setPdfActionNotice(
            t("pdfViewer.compressSaved", {
              percent: Math.round(
                (options.result.savedBytes / options.result.originalSize) * 100,
              ),
              saved: `${Math.max(
                1,
                Math.round(options.result.savedBytes / 1024),
              )} KB`,
            }),
            "status",
          );
          return true;
        } finally {
          blobBytes.fill(0);
          setTimeout(() => URL.revokeObjectURL(objectUrl), 60_000); // WebKit reads a large download well after the click task
        }
      });
      const runtime = {
        featureFlags: readPdfFeatureFlagState(),
        decisions: {
          [PDF_READER_COMPRESS_LOSSLESS_COMMAND.featureId]: {
            enabled: true,
            disposition: view.disposition,
            savePolicy: {
              request: options.request,
              decision: options.decision,
            },
            reasonKey: view.reasonKey ?? undefined,
          },
        },
      } satisfies PdfFeatureRuntimeState;
      const context: PdfCapabilityContext = {
        host: "reader",
        documentReady: savePolicyRuntimeRef.current.documentReady,
        editable: savePolicyRuntimeRef.current.editable,
      };
      return (
        (await authority.execute(
          PDF_READER_COMPRESS_LOSSLESS_COMMAND,
          context,
          runtime,
        )) === "executed"
      );
    },
    [
      commandInstanceId,
      createReaderSavePolicyRequest,
      rememberFileOpResult,
      requestOutputConsent,
      t,
    ],
  );

  const executeLossyCompressionOutput = useCallback(
    async (options: {
      readonly request: PdfSavePolicyRequest;
      readonly decision: PdfSavePolicyDecision;
      readonly lossReport: PdfOutputLossReport;
      readonly policyContext: PdfLossyCompressionPolicyContext;
      readonly plan: PdfLossyCompressionEvidencePlan;
      readonly sourceKey: string;
      readonly outputName: string;
      readonly operationGeneration: number;
      readonly outputAuthorityIsCurrent: () => boolean;
    }): Promise<boolean> => {
      const view = readPdfSavePolicyDecision(options.decision);
      if (!view?.enabled) return false;
      const optionRevision = `compress-lossy:${options.plan.preset}:${options.plan.evidenceDigest}`;
      const currentRequest = () =>
        createReaderSavePolicyRequest({
          action: "pdf.file.compress-lossy",
          disposition: "flatten-with-consent",
          hasEdits: true,
          lossReport: options.lossReport,
          optionRevision,
          lossyCompression: options.policyContext,
          editable: lossyCompressionRuntimeRef.current.writable,
        });
      const isCurrent = () =>
        compressionHostMountedRef.current &&
        losslessCompressionGenerationRef.current ===
          options.operationGeneration &&
        compressPresetRuntimeRef.current === options.plan.preset &&
        lossyCompressionRuntimeRef.current.writable &&
        options.outputAuthorityIsCurrent() &&
        pdfCompressionEvidenceSourceKey(
          lossyCompressionRuntimeRef.current.source,
        ) === options.sourceKey &&
        verifyPdfSavePolicyDecision(options.decision, currentRequest());
      if (!isCurrent()) return false;
      const operationOwner = createPdfCommandAuthorityOwner({
        host: "reader",
        instanceId: `${commandInstanceId}:lossy-compress:${options.operationGeneration}`,
        invocation: PDF_READER_COMPRESS_LOSSY_COMMAND,
      });
      const authority = operationOwner.bind(async () => {
        if (!isCurrent()) return false;
        const receipt = await requestOutputConsent(
          options.request,
          options.decision,
        );
        if (!receipt || !isCurrent()) return false;
        const exactCurrentRequest = currentRequest();
        if (
          !consumePdfSavePolicyConsentReceipt({
            receipt,
            documentAuthority: savePolicyRuntimeRef.current.documentAuthority,
            decision: options.decision,
            currentRequest: exactCurrentRequest,
          }) ||
          !isCurrent()
        ) {
          return false;
        }
        let result: Awaited<
          ReturnType<typeof executePdfLossyCompressionEvidencePlan>
        > | null = null;
        try {
          result = await executePdfLossyCompressionEvidencePlan(
            options.plan,
            isCurrent,
          );
          if (!isCurrent()) return false;
          if (result.savedBytes === 0) {
            setPdfActionNotice(t("pdfViewer.compressNoGain"), "status");
            return true;
          }
          const blobBytes = new Uint8Array(result.bytes.byteLength);
          blobBytes.set(result.bytes);
          if (!isCurrent()) {
            blobBytes.fill(0);
            return false;
          }
          const objectUrl = URL.createObjectURL(
            new Blob([blobBytes], { type: "application/pdf" }),
          );
          try {
            const link = document.createElement("a");
            link.href = objectUrl;
            link.download = options.outputName;
            document.body.appendChild(link);
            if (!isCurrent()) {
              link.remove();
              return false;
            }
            link.click();
            link.remove();
            if (!isCurrent()) return false;
            rememberFileOpResult(blobBytes, options.outputName);
            if (!isCurrent()) return false;
            setPdfActionNotice(
              t("pdfViewer.compressSaved", {
                percent: Math.round(
                  (result.savedBytes / result.originalSize) * 100,
                ),
                saved: `${Math.max(
                  1,
                  Math.round(result.savedBytes / 1024),
                )} KB`,
              }),
              "status",
            );
            return true;
          } finally {
            blobBytes.fill(0);
            setTimeout(() => URL.revokeObjectURL(objectUrl), 60_000); // WebKit reads a large download well after the click task
          }
        } finally {
          result?.bytes.fill(0);
        }
      });
      const runtime = {
        featureFlags: readPdfFeatureFlagState(),
        decisions: {
          [PDF_READER_COMPRESS_LOSSY_COMMAND.featureId]: {
            enabled: true,
            disposition: view.disposition,
            savePolicy: {
              request: options.request,
              decision: options.decision,
            },
            reasonKey: view.reasonKey ?? undefined,
          },
        },
      } satisfies PdfFeatureRuntimeState;
      const context: PdfCapabilityContext = {
        host: "reader",
        documentReady: savePolicyRuntimeRef.current.documentReady,
        editable: lossyCompressionRuntimeRef.current.writable,
      };
      return (
        (await authority.execute(
          PDF_READER_COMPRESS_LOSSY_COMMAND,
          context,
          runtime,
        )) === "executed"
      );
    },
    [
      commandInstanceId,
      createReaderSavePolicyRequest,
      rememberFileOpResult,
      requestOutputConsent,
      t,
    ],
  );

  // "Compress": the P0.03 exact path restores only the local structural
  // writer. The server-owned screen/ebook/print presets stay blocked while the
  // policy flag is enabled and can never fall back to the local writer.
  const handleCompressPdf = useCallback(async (
    requestedPreset: PdfCompressPreset = compressPreset,
  ) => {
    if (loadingNowRef.current && !(await waitForShownRevision())) return;
    if (
      !compressionHostMountedRef.current ||
      flattening ||
      losslessCompressionInFlightRef.current
    ) {
      return;
    }
    const outputAction: PdfSavePolicyAction =
      requestedPreset === PDF_COMPRESS_LOSSLESS_PRESET
        ? "pdf.file.compress-lossless"
        : "pdf.file.compress-lossy";
    if (
      blockVisualMaskDerivedPdfOutput(outputAction)
    ) {
      return;
    }
    const visualMaskOutputIsCurrent =
      createVisualMaskOutputAuthorityGuard(outputAction);
    if (!visualMaskOutputIsCurrent) return;
    const operationGeneration = ++losslessCompressionGenerationRef.current;
    const isMountedCompressionOperation = () =>
      compressionHostMountedRef.current &&
      losslessCompressionGenerationRef.current === operationGeneration;
    const isCurrentCompressionOperation = () =>
      isMountedCompressionOperation() &&
      compressPresetRuntimeRef.current === requestedPreset &&
      visualMaskOutputIsCurrent();
    const rejectStaleCompressionOperation = () => {
      if (!isMountedCompressionOperation()) return true;
      if (isCurrentCompressionOperation()) return false;
      setPdfActionNotice("pdf.savePolicy.staleAuthority");
      return true;
    };
    losslessCompressionInFlightRef.current = true;
    beginOutputAttempt();
    setFlattening(true);
    try {
      if (requestedPreset !== PDF_COMPRESS_LOSSLESS_PRESET) {
        if (!savePolicyV1) {
          if (blockAdjacentPdfOutput()) return;
          const serverItemId = dataItemId ?? dataItemIdFromPreviewUrl(url);
          if (!serverItemId) {
            setPdfActionNotice(t("pdfViewer.compressFailed"));
            return;
          }
          const result = await compressPdfServerSideWithStats(
            serverItemId,
            requestedPreset,
          );
          if (rejectStaleCompressionOperation()) {
            result.bytes.fill(0);
            return;
          }
          if (result.savedBytes > 0) {
            const blobBytes = new Uint8Array(result.bytes.byteLength);
            blobBytes.set(result.bytes);
            if (rejectStaleCompressionOperation()) {
              blobBytes.fill(0);
              return;
            }
            const outputName = `${(filename || "document.pdf").replace(
              /\.pdf$/i,
              "",
            )}-compressed.pdf`;
            const blob = new Blob([blobBytes], { type: "application/pdf" });
            if (rejectStaleCompressionOperation()) {
              blobBytes.fill(0);
              return;
            }
            downloadBlobFile(outputName, blob);
            if (rejectStaleCompressionOperation()) {
              blobBytes.fill(0);
              return;
            }
            rememberFileOpResult(
              blobBytes,
              outputName,
            );
            setPdfActionNotice(
              t("pdfViewer.compressSaved", {
                percent: Math.round(
                  (result.savedBytes / result.originalSize) * 100,
                ),
                saved: `${Math.max(
                  1,
                  Math.round(result.savedBytes / 1024),
                )} KB`,
              }),
              "status",
            );
          } else {
            setPdfActionNotice(t("pdfViewer.compressNoGain"), "status");
          }
          return;
        }

        const requestedSource = lossyCompressionRuntimeRef.current.source;
        const requestedWritable = lossyCompressionRuntimeRef.current.writable;
        const requestedRiskSnapshot = savePolicyRuntimeRef.current.source;
        const requestedSourceKey =
          pdfCompressionEvidenceSourceKey(requestedSource);
        const requestedEditRevision =
          savePolicyEditRevisionRef.current.revision;
        const requestedHasEditorEdits =
          hasFlattenableAnnotations || hasNativeFormEditsExcludedFromSource;
        if (
          !requestedSource ||
          !requestedSourceKey ||
          !requestedWritable ||
          !requestedRiskSnapshot ||
          requestedSource.expectedSha256 !==
            requestedRiskSnapshot.identity.sha256 ||
          (requestedSource.kind === "data_item" &&
            requestedSource.dataItemId !==
              requestedRiskSnapshot.identity.dataItemId)
        ) {
          setPdfActionNotice("pdf.savePolicy.sourceIdentityRequired");
          return;
        }
        const plan = await requestPdfLossyCompressionEvidencePlan(
          requestedSource,
          requestedPreset,
        );
        if (rejectStaleCompressionOperation()) return;
        // No picture this preset may shrink: the file is as small as the
        // preset makes it (WPS reports the same), not a failure.
        if (plan.transformedObjectCount === 0) {
          setPdfActionNotice(t("pdfViewer.compressNoGain"), "status");
          return;
        }
        const optionRevision = `compress-lossy:${requestedPreset}:${plan.evidenceDigest}`;
        const policyContext = createPdfLossyCompressionPolicyContext({
          previewDataItemId: requestedRiskSnapshot.identity.dataItemId,
          previewByteGenerationKey:
            requestedRiskSnapshot.identity.byteGenerationKey,
          previewSha256: requestedRiskSnapshot.identity.sha256,
          documentRevision: requestedRiskSnapshot.identity.documentRevision,
          editRevision: `${requestedEditRevision}:${optionRevision}`,
          sourceKind: plan.source.kind,
          workspaceId: plan.source.workspaceId,
          datasetId: plan.source.datasetId,
          dataItemId: plan.source.dataItemId,
          resourceId: plan.source.resourceId,
          resourceVersionId: plan.source.resourceVersionId,
          versionKind: plan.source.versionKind,
          expectedPageId: plan.source.expectedPageId,
          storageCustodyDigest: plan.source.storageCustodyDigest,
          sourceSize: plan.source.size,
          preset: plan.preset,
          targetDpi: plan.targetDpi,
          jpegQuality: plan.jpegQuality,
          pageCount: plan.pageCount,
          transformedObjectCount: plan.transformedObjectCount,
          nativePlanDigest: plan.nativePlanDigest,
          evidenceDigest: plan.evidenceDigest,
        });
        const lossReport = createPdfOutputLossReportForAction(
          "pdf.file.compress-lossy",
          requestedHasEditorEdits
            ? [PDF_LOSS_CURRENT_EDITOR_EDITS_EXCLUDED]
            : [],
        );
        const request = createReaderSavePolicyRequest({
          action: "pdf.file.compress-lossy",
          disposition: "flatten-with-consent",
          hasEdits: true,
          lossReport,
          optionRevision,
          lossyCompression: policyContext,
          source: requestedRiskSnapshot,
          editable: requestedWritable,
        });
        const policy = resolveReaderSavePolicy(request);
        const liveRequest = createReaderSavePolicyRequest({
          action: "pdf.file.compress-lossy",
          disposition: "flatten-with-consent",
          hasEdits: true,
          lossReport,
          optionRevision,
          lossyCompression: policyContext,
          editable: lossyCompressionRuntimeRef.current.writable,
        });
        if (
          !policy.view?.enabled ||
          !verifyPdfSavePolicyDecision(policy.decision, liveRequest) ||
          pdfCompressionEvidenceSourceKey(
            lossyCompressionRuntimeRef.current.source,
          ) !== requestedSourceKey ||
          compressPresetRuntimeRef.current !== requestedPreset ||
          losslessCompressionGenerationRef.current !== operationGeneration
        ) {
          if (isMountedCompressionOperation()) {
            setPdfActionNotice(
              policy.view?.reasonKey ?? "pdf.savePolicy.staleAuthority",
            );
          }
          return;
        }
        await executeLossyCompressionOutput({
          request,
          decision: policy.decision,
          lossReport,
          policyContext,
          plan,
          sourceKey: requestedSourceKey,
          outputName: `${(filename || "document.pdf").replace(
            /\.pdf$/i,
            "",
          )}-compressed.pdf`,
          operationGeneration,
          outputAuthorityIsCurrent: visualMaskOutputIsCurrent,
        });
        return;
      }

      const requestedDataItemId = dataItemId;
      const requestedByteGenerationKey = expectedSourceByteGenerationKey;
      const requestedDocumentRevision = sourceDocumentRevisionRef.current;
      const requestedEditRevision =
        savePolicyEditRevisionRef.current.revision;
      const requestedHasEditorEdits =
        hasFlattenableAnnotations || hasNativeFormEditsExcludedFromSource;
      if (savePolicyV1 && !requestedDataItemId) {
        setPdfActionNotice("pdf.savePolicy.sourceIdentityRequired");
        return;
      }
      const response = await fetchPdfSource(url);
      if (!response.ok) throw new Error(`${response.status}`.trim());
      const sourceBytes = await readBoundedPdfResponse(response);
      if (rejectStaleCompressionOperation()) {
        sourceBytes.fill(0);
        return;
      }

      if (!savePolicyV1) {
        const result = await documentWritersRef.current.compressPdfWithStats(sourceBytes, {
          preset: PDF_COMPRESS_LOSSLESS_PRESET,
        });
        if (rejectStaleCompressionOperation()) {
          result.bytes.fill(0);
          return;
        }
        if (result.savedBytes === 0) {
          setPdfActionNotice(t("pdfViewer.compressNoGain"), "status");
          return;
        }
        const blobBytes = new Uint8Array(result.bytes.byteLength);
        blobBytes.set(result.bytes);
        const outputName = `${(filename || "document.pdf").replace(
          /\.pdf$/i,
          "",
        )}-compressed.pdf`;
        if (rejectStaleCompressionOperation()) {
          blobBytes.fill(0);
          return;
        }
        const blob = new Blob([blobBytes], { type: "application/pdf" });
        if (rejectStaleCompressionOperation()) {
          blobBytes.fill(0);
          return;
        }
        downloadBlobFile(outputName, blob);
        if (rejectStaleCompressionOperation()) {
          blobBytes.fill(0);
          return;
        }
        rememberFileOpResult(blobBytes, outputName);
        setPdfActionNotice(
          t("pdfViewer.compressSaved", {
            percent: Math.round(
              (result.savedBytes / result.originalSize) * 100,
            ),
            saved: `${Math.max(1, Math.round(result.savedBytes / 1024))} KB`,
          }),
          "status",
        );
        return;
      }

      const inspectedSource = await inspectPdfSourceRiskSnapshot({
        dataItemId: requestedDataItemId!,
        byteGenerationKey: requestedByteGenerationKey,
        bytes: sourceBytes,
        documentRevision: requestedDocumentRevision,
      });
      if (rejectStaleCompressionOperation()) return;
      if (
        savePolicyEditRevisionRef.current.revision !== requestedEditRevision
      ) {
        setPdfActionNotice("pdf.savePolicy.staleAuthority");
        return;
      }
      const lossReport = createPdfOutputLossReportForAction(
        "pdf.file.compress-lossless",
        requestedHasEditorEdits
          ? [PDF_LOSS_CURRENT_EDITOR_EDITS_EXCLUDED]
          : [],
      );
      const request = createReaderSavePolicyRequest({
        action: "pdf.file.compress-lossless",
        disposition: "flatten-with-consent",
        hasEdits: true,
        lossReport,
        optionRevision: `compress:${PDF_COMPRESS_LOSSLESS_PRESET}`,
        source: inspectedSource,
      });
      const policy = resolveReaderSavePolicy(request);
      if (!policy.view?.enabled) {
        setPdfActionNotice(
          policy.view?.reasonKey ?? t("pdfViewer.compressFailed"),
        );
        return;
      }
      const liveRequest = createReaderSavePolicyRequest({
        action: "pdf.file.compress-lossless",
        disposition: "flatten-with-consent",
        hasEdits: true,
        lossReport,
        optionRevision: `compress:${compressPresetRuntimeRef.current}`,
      });
      if (!verifyPdfSavePolicyDecision(policy.decision, liveRequest)) {
        setPdfActionNotice("pdf.savePolicy.staleAuthority");
        return;
      }

      const result = await documentWritersRef.current.compressPdfWithStats(sourceBytes, {
        preset: PDF_COMPRESS_LOSSLESS_PRESET,
      });
      if (rejectStaleCompressionOperation()) {
        result.bytes.fill(0);
        return;
      }
      if (result.savedBytes === 0) {
        setPdfActionNotice(t("pdfViewer.compressNoGain"), "status");
        return;
      }
      await executeLosslessCompressionOutput({
        request,
        decision: policy.decision,
        lossReport,
        result,
        outputName: `${(filename || "document.pdf").replace(
          /\.pdf$/i,
          "",
        )}-compressed.pdf`,
        operationGeneration,
        outputAuthorityIsCurrent: visualMaskOutputIsCurrent,
      });
    } catch {
      if (isMountedCompressionOperation()) {
        setPdfActionNotice(
          isCurrentCompressionOperation()
            ? t("pdfViewer.compressFailed")
            : "pdf.savePolicy.staleAuthority",
        );
      }
    } finally {
      losslessCompressionInFlightRef.current = false;
      if (isMountedCompressionOperation()) setFlattening(false);
    }
  }, [
    beginOutputAttempt,
    blockAdjacentPdfOutput,
    blockVisualMaskDerivedPdfOutput,
    compressPreset,
    createReaderSavePolicyRequest,
    createVisualMaskOutputAuthorityGuard,
    dataItemId,
    executeLosslessCompressionOutput,
    executeLossyCompressionOutput,
    expectedSourceByteGenerationKey,
    filename,
    flattening,
    hasFlattenableAnnotations,
    hasNativeFormEditsExcludedFromSource,
    loading,
    rememberFileOpResult,
    resolveReaderSavePolicy,
    savePolicyV1,
    t,
    url,
  ]);

  const applyCompressSettings = useCallback(
    (preset: PdfCompressPreset) => {
      compressPresetRuntimeRef.current = preset;
      setCompressPreset(preset);
      setCompressSettingsOpen(false);
      queueMicrotask(() => void handleCompressPdf(preset));
    },
    [handleCompressPdf],
  );

  // Export the AcroForm name->value pairs from the ORIGINAL bytes as the
  // selected typed interchange format. Live overlay values are applied to the
  // disposable document before CSV/XFDF serialization, without rewriting the
  // source PDF.
  const handleExportFormData = useCallback(async (
    requestedFormat: PdfFormDataFormat = formDataExportFormat,
  ) => {
    if (flattening || loading || formDataExportInFlightRef.current) return;
    const requestedLoadedSource = loadedPdfSourceIdentityRef.current;
    const requestedRetainedSource = retainedPdfPrintSourceBytesRef.current;
    const requestedFormValues = formValuesRef.current;
    const requestedDocumentRevision = sourceDocumentRevisionRef.current;
    if (
      !requestedLoadedSource ||
      !requestedRetainedSource ||
      !requestedLoadedSource.dataItemId ||
      requestedLoadedSource.dataItemId !== dataItemId ||
      requestedLoadedSource.url !== url ||
      requestedLoadedSource.byteGenerationKey !==
        expectedSourceByteGenerationKey ||
      requestedLoadedSource.documentRevision !== requestedDocumentRevision ||
      requestedRetainedSource.document !== requestedLoadedSource.document ||
      requestedRetainedSource.dataItemId !== requestedLoadedSource.dataItemId ||
      requestedRetainedSource.url !== requestedLoadedSource.url ||
      requestedRetainedSource.byteGenerationKey !==
        requestedLoadedSource.byteGenerationKey ||
      requestedRetainedSource.documentRevision !== requestedDocumentRevision ||
      !/^[0-9a-f]{64}$/.test(requestedRetainedSource.sha256)
    ) {
      setPdfActionNotice(t("pdfViewer.exportFormDataFailed"));
      return;
    }
    const authorityIsCurrent = () =>
      loadedPdfSourceIdentityRef.current === requestedLoadedSource &&
      retainedPdfPrintSourceBytesRef.current === requestedRetainedSource &&
      sourceDocumentRevisionRef.current === requestedDocumentRevision &&
      formValuesRef.current === requestedFormValues &&
      formDataExportFormatRef.current === requestedFormat;
    formDataExportInFlightRef.current = true;
    beginOutputAttempt();
    setFlattening(true);
    let sourceBytes: Uint8Array | null = null;
    try {
      sourceBytes = new Uint8Array(requestedRetainedSource.bytes.byteLength);
      sourceBytes.set(requestedRetainedSource.bytes);
      if (
        !authorityIsCurrent() ||
        (await pdfBytesSha256(sourceBytes)) !== requestedRetainedSource.sha256
      ) {
        return;
      }
      // The user's interactive fills live in the `pdf_form_values` annotation
      // (formValues), NOT in the fetched source bytes — overlay them so the CSV
      // exports what they entered, mirroring the annotated-download path. A
      // boolean check-box value maps to a truthy/empty token applyFormFieldValues
      // understands.
      const overrides: PdfFormFieldValue[] = Object.entries(
        requestedFormValues,
      ).map(
        ([name, value]) =>
          Array.isArray(value)
            ? { name, value: value.join(", "), values: value.slice() }
            : {
                name,
                value:
                  typeof value === "boolean"
                    ? value
                      ? "true"
                      : ""
                    : value,
              },
      );
      const result = await exportPdfFormData(
        sourceBytes,
        requestedFormat,
        overrides,
      );
      if (!authorityIsCurrent()) return;
      if (result.fieldCount === 0) {
        setPdfActionNotice(t("pdfViewer.exportFormDataEmpty"), "status");
      } else {
        const base = (filename || "document.pdf").replace(/\.pdf$/i, "");
        const isCsv = result.format === "csv";
        const extension = isCsv ? "csv" : "xfdf";
        const blob = new Blob(isCsv ? ["﻿", result.data] : [result.data], {
          type: isCsv
            ? "text/csv;charset=utf-8"
            : "application/vnd.adobe.xfdf;charset=utf-8",
        });
        if (!authorityIsCurrent()) return;
        downloadBlobFile(`${base}-form-data.${extension}`, blob);
      }
    } catch (error) {
      if (!authorityIsCurrent()) return;
      // The exporter refuses rather than writing stale or blank values for a
      // field it cannot represent or read; name those fields so the reader
      // knows what to fix instead of guessing why the download did not start.
      if (
        error instanceof PdfFormRewriteBoundaryError &&
        error.issues.length > 0 &&
        (error.code === "override_rejected" ||
          error.code === "field_unreadable" ||
          error.code === "csv_unsupported" ||
          error.code === "xfdf_unsupported")
      ) {
        const names = [
          ...new Set(
            error.issues.map((issue) => issue.name ?? t("pdfViewer.exportFormDataUnnamedField")),
          ),
        ];
        const shown = names.slice(0, 5);
        setPdfActionNotice(
          t(
            error.code === "override_rejected"
              ? "pdfViewer.exportFormDataRejected"
              : "pdfViewer.exportFormDataUnreadable",
            {
              count: names.length,
              fields:
                names.length > shown.length
                  ? `${shown.join(", ")} +${names.length - shown.length}`
                  : shown.join(", "),
            },
          ),
        );
        return;
      }
      setPdfActionNotice(t("pdfViewer.exportFormDataFailed"));
    } finally {
      sourceBytes?.fill(0);
      formDataExportInFlightRef.current = false;
      setFlattening(false);
      // The export answers from the engine host (B4.2a): the dialog returned
      // focus to its trigger before the busy state disabled it, so give it
      // back once the trigger is enabled again, unless the reader moved on.
      const trigger = formDataExportDialogReturnFocusRef.current;
      requestAnimationFrame(() => {
        if (
          trigger?.isConnected &&
          (document.activeElement === document.body ||
            document.activeElement === null)
        ) {
          trigger.focus({ preventScroll: true });
        }
      });
    }
  }, [
    beginOutputAttempt,
    dataItemId,
    expectedSourceByteGenerationKey,
    filename,
    flattening,
    formDataExportFormat,
    loading,
    t,
    url,
  ]);

  // Reset form data only through the typed native AcroForm writer. A reader
  // without that authority is explicitly disabled; it must never manufacture
  // a flattened derivative that looks like a current-document reset.
  // A reset button that names fields resets only those (or, excluding,
  
  const handleResetForm = useCallback(async (scope?: PdfResetFormScope) => {
    if (flattening || loading || formValueOutputInFlightRef.current) return;
    if (blockNativeFormDataMutation()) return;
    const operationGeneration = ++formValueOutputGenerationRef.current;
    formValueOutputInFlightRef.current = true;
    setPdfActionNotice(null);
    setFlattening(true);
    let sourceBytes: Uint8Array | null = null;
    try {
      if (!(await flushFormValues({ includeOpenNativeGesture: true }))) {
        setPdfActionNotice(t("pdfViewer.resetFormFailed"));
        return;
      }
      const requestedDataItemId = dataItemId;
      const requestedUrl = url;
      const requestedByteGenerationKey = expectedSourceByteGenerationKey;
      const requestedDocumentRevision = sourceDocumentRevisionRef.current;
      const requestedEditRevision = savePolicyEditRevisionRef.current.revision;
      if (!requestedDataItemId) {
        setPdfActionNotice("pdf.savePolicy.sourceIdentityRequired");
        return;
      }
      const response = await fetchPdfSource(requestedUrl);
      if (!response.ok) throw new Error(`${response.status}`.trim());
      sourceBytes = await readBoundedPdfResponse(response);

      const inspectedSource = await inspectPdfSourceRiskSnapshot({
        dataItemId: requestedDataItemId,
        byteGenerationKey: requestedByteGenerationKey,
        bytes: sourceBytes,
        documentRevision: requestedDocumentRevision,
      });
      // The edit revision follows the annotated-bytes builder, which is
      // rebuilt whenever its inputs get new identities (this reset's own busy
      // state, a form value acknowledged, a page rendering) with nothing
      // edited. Reset writes the verified source's form values and never
      
      // it is stale only when the source moved or an output edit appeared.
      if (
        formValueOutputGenerationRef.current !== operationGeneration ||
        sourceDocumentRevisionRef.current !== requestedDocumentRevision ||
        (hasEffectivePdfOutputEditsRef.current &&
          savePolicyEditRevisionRef.current.revision !== requestedEditRevision)
      ) {
        setPdfActionNotice("pdf.savePolicy.staleAuthority");
        return;
      }
      const resetPlan: PdfFormResetPlan =
        await preflightPdfFormReset(sourceBytes, scope);
      if (resetPlan.fieldCount === 0) {
        setPdfActionNotice(t("pdfViewer.exportFormDataEmpty"), "status");
        return;
      }
      const planDigest = await createPdfOutputPlanDigest([
        "pdf.form.reset-values",
        resetPlan.scope
          ? `reset-${resetPlan.scope.include ? "named" : "all-but-named"}-fields:` +
            JSON.stringify([resetPlan.scope.fields, resetPlan.scope.refs])
          : "reset-all-supported-fields",
        String(resetPlan.fieldCount),
      ]);
      const executed = await executeNativeFormValuePlan({
        invocation: PDF_READER_RESET_FORM_VALUES_COMMAND,
        action: "pdf.form.reset-values",
        planDigest,
        operationGeneration,
        source: inspectedSource,
        updates: resetPlan.updates,
      });
      if (!executed) setPdfActionNotice(t("pdfViewer.resetFormFailed"));
    } catch {
      setPdfActionNotice(t("pdfViewer.resetFormFailed"));
    } finally {
      sourceBytes?.fill(0);
      formValueOutputInFlightRef.current = false;
      setFlattening(false);
    }
  }, [
    blockNativeFormDataMutation,
    dataItemId,
    executeNativeFormValuePlan,
    expectedSourceByteGenerationKey,
    flattening,
    flushFormValues,
    loading,
    t,
    url,
  ]);

  // Import form data only through one typed native AcroForm gesture. Annotation
  // XFDF remains a separate authority, and no derivative PDF fallback exists.
  const handleImportFormDataPicked = useCallback(
    async (files: FileList | null) => {
      const file = files?.[0];
      if (!file || loading) return;
      const format = resolvePdfFormDataFormatForFile(file);
      if (!format) {
        setPdfActionNotice(t("pdfViewer.importFormDataFailed"));
        return;
      }
      // A later recognized picker result is authoritative user intent. Advance
      // the generation before the busy guard so an older consent receipt or
      // writer result can never publish after that newer selection.
      const operationGeneration = ++formValueOutputGenerationRef.current;
      if (flattening || formValueOutputInFlightRef.current) return;
      if (blockNativeFormDataMutation()) return;
      const requestedLoadedSource = loadedPdfSourceIdentityRef.current;
      const requestedRetainedSource = retainedPdfPrintSourceBytesRef.current;
      const requestedDataItemId = dataItemId;
      const requestedDocumentRevision = sourceDocumentRevisionRef.current;
      let requestedEditRevision: number | null = null;
      if (
        !requestedLoadedSource ||
        !requestedRetainedSource ||
        !requestedDataItemId ||
        requestedLoadedSource.dataItemId !== requestedDataItemId ||
        requestedLoadedSource.url !== url ||
        requestedLoadedSource.byteGenerationKey !==
          expectedSourceByteGenerationKey ||
        requestedLoadedSource.documentRevision !==
          requestedDocumentRevision ||
        requestedRetainedSource.document !== requestedLoadedSource.document ||
        requestedRetainedSource.dataItemId !== requestedDataItemId ||
        requestedRetainedSource.url !== requestedLoadedSource.url ||
        requestedRetainedSource.byteGenerationKey !==
          requestedLoadedSource.byteGenerationKey ||
        requestedRetainedSource.documentRevision !==
          requestedDocumentRevision ||
        !/^[0-9a-f]{64}$/.test(requestedRetainedSource.sha256)
      ) {
        setPdfActionNotice(t("pdfViewer.importFormDataFailed"));
        return;
      }
      const authorityIsCurrent = () =>
        formValueOutputGenerationRef.current === operationGeneration &&
        loadedPdfSourceIdentityRef.current === requestedLoadedSource &&
        retainedPdfPrintSourceBytesRef.current === requestedRetainedSource &&
        sourceDocumentRevisionRef.current === requestedDocumentRevision &&
        (requestedEditRevision === null ||
          savePolicyEditRevisionRef.current.revision === requestedEditRevision);
      formValueOutputInFlightRef.current = true;
      setPdfActionNotice(null);
      setFlattening(true);
      let formDataBytes: Uint8Array | null = null;
      let sourceBytes: Uint8Array | null = null;
      try {
        if (
          !Number.isSafeInteger(file.size) ||
          file.size < 1 ||
          file.size > PDF_FORM_IMPORT_MAX_DATA_BYTES
        ) {
          throw new Error("Invalid PDF form-data file size");
        }
        const formDataBuffer = await file.arrayBuffer();
        if (!authorityIsCurrent()) return;
        formDataBytes = new Uint8Array(formDataBuffer);
        if (formDataBytes.byteLength !== file.size) {
          throw new Error("PDF form-data file changed while reading");
        }
        const formData = new TextDecoder("utf-8", { fatal: true }).decode(
          formDataBytes,
        );
        if (!(await flushFormValues({ includeOpenNativeGesture: true }))) {
          setPdfActionNotice(t("pdfViewer.importFormDataFailed"));
          return;
        }
        if (!authorityIsCurrent()) return;
        requestedEditRevision = savePolicyEditRevisionRef.current.revision;

        const formDataSha256 = await createPdfBoundedInputDigest(
          formDataBytes,
          PDF_FORM_IMPORT_MAX_DATA_BYTES,
        );
        if (!authorityIsCurrent()) return;
        sourceBytes = new Uint8Array(requestedRetainedSource.bytes.byteLength);
        sourceBytes.set(requestedRetainedSource.bytes);
        const inspectedSource = await inspectPdfSourceRiskSnapshot({
          dataItemId: requestedDataItemId,
          byteGenerationKey: requestedLoadedSource.byteGenerationKey,
          bytes: sourceBytes,
          documentRevision: requestedDocumentRevision,
        });
        if (
          !authorityIsCurrent() ||
          inspectedSource.identity.dataItemId !== requestedDataItemId ||
          inspectedSource.identity.byteGenerationKey !==
            requestedLoadedSource.byteGenerationKey ||
          inspectedSource.identity.documentRevision !==
            requestedDocumentRevision ||
          inspectedSource.identity.sha256 !== requestedRetainedSource.sha256
        ) {
          setPdfActionNotice("pdf.savePolicy.staleAuthority");
          return;
        }
        const importPlan: PdfFormImportPlan = await preflightPdfFormDataImport(
          sourceBytes,
          formData,
          format,
        );
        if (!authorityIsCurrent()) return;
        if (importPlan.applied === 0) {
          setPdfActionNotice(t("pdfViewer.importFormDataEmpty"), "status");
          return;
        }
        const planDigest = await createPdfOutputPlanDigest([
          "pdf.form.import-data",
          `${format}-v1`,
          String(formDataBytes.byteLength),
          formDataSha256,
          String(importPlan.entryCount),
          String(importPlan.applied),
          String(importPlan.skipped),
          String(importPlan.skippedByReason.field_not_found),
          String(importPlan.skippedByReason.invalid_value),
          String(importPlan.skippedByReason.read_only),
          String(importPlan.skippedByReason.required_empty),
          String(importPlan.skippedByReason.unsupported_field),
        ]);
        const executed = await executeNativeFormValuePlan({
          invocation: PDF_READER_IMPORT_FORM_DATA_COMMAND,
          action: "pdf.form.import-data",
          planDigest,
          operationGeneration,
          source: inspectedSource,
          updates: importPlan.updates,
        });
        setPdfActionNotice(
          executed
            ? t("pdfViewer.importFormDataDone", {
                applied: importPlan.applied,
                skipped: importPlan.skipped,
              })
            : t("pdfViewer.importFormDataFailed"),
          executed ? "status" : "error",
        );
      } catch {
        if (authorityIsCurrent()) {
          setPdfActionNotice(t("pdfViewer.importFormDataFailed"));
        }
      } finally {
        formDataBytes?.fill(0);
        sourceBytes?.fill(0);
        formValueOutputInFlightRef.current = false;
        setFlattening(false);
      }
    },
    [
      blockNativeFormDataMutation,
      dataItemId,
      executeNativeFormValuePlan,
      expectedSourceByteGenerationKey,
      flattening,
      flushFormValues,
      loading,
      t,
      url,
    ],
  );

  // A browser that cannot show a PDF in a frame prints the pages the reader
  // draws itself, one picture per page at its own paper size (user audit
  // PDF 0046: every print there ended in 「无法打印这个 PDF」).
  const invokeRasterPrint = useCallback(
    async (
      bytes: Uint8Array,
      authorityIsCurrent: () => boolean,
    ): Promise<boolean> => {
      const frame = printFrameRef.current;
      if (!frame || !authorityIsCurrent()) return false;
      const urls: string[] = [];
      let printed = false;
      const pdfjs = await loadPdfApi();
      const task = pdfjs.getDocument({
        data: Uint8Array.from(bytes),
        ...PDF_JS_DOCUMENT_ASSETS,
      });
      try {
        const document_ = await task.promise;
        const pages: PdfRasterPrintPage[] = [];
        for (let pageNumber = 1; pageNumber <= document_.numPages; pageNumber += 1) {
          if (!authorityIsCurrent()) return false;
          const page = await document_.getPage(pageNumber);
          const paper = page.getViewport({ scale: 1 });
          const viewport = page.getViewport({ scale: PDF_RASTER_PRINT_DPI / 72 });
          const canvas = document.createElement("canvas");
          canvas.width = Math.max(1, Math.ceil(viewport.width - 1e-6));
          canvas.height = Math.max(1, Math.ceil(viewport.height - 1e-6));
          const context = canvas.getContext("2d");
          if (!context) return false;
          context.fillStyle = "#ffffff";
          context.fillRect(0, 0, canvas.width, canvas.height);
          await page.render({ canvas, canvasContext: context, viewport, intent: "print" }).promise;
          const blob = await new Promise<Blob | null>((resolve) =>
            canvas.toBlob(resolve, "image/jpeg", 0.92),
          );
          canvas.width = 0;
          canvas.height = 0;
          page.cleanup();
          if (!blob) return false;
          const url = URL.createObjectURL(blob);
          urls.push(url);
          pages.push({ url, widthIn: paper.width / 72, heightIn: paper.height / 72 });
        }
        if (!authorityIsCurrent()) return false;
        printed = await new Promise<boolean>((resolve) => {
          let settled = false;
          const settle = (value: boolean) => {
            if (settled) return;
            settled = true;
            window.clearTimeout(timeoutId);
            frame.onload = null;
            resolve(value);
          };
          const timeoutId = window.setTimeout(() => settle(false), 20_000);
          frame.onload = () => {
            void (async () => {
              try {
                const frameDocument = frame.contentDocument;
                const printWindow = frame.contentWindow;
                if (!frameDocument || !printWindow || !authorityIsCurrent()) {
                  settle(false);
                  return;
                }
                await Promise.all(
                  Array.from(frameDocument.images).map((image) =>
                    image.decode().catch(() => undefined),
                  ),
                );
                if (!authorityIsCurrent()) {
                  settle(false);
                  return;
                }
                printWindow.focus();
                printWindow.print();
                settle(true);
              } catch {
                settle(false);
              }
            })();
          };
          frame.removeAttribute("src");
          frame.srcdoc = rasterPrintDocumentHtml(pages);
        });
        return printed;
      } catch {
        return false;
      } finally {
        void task.destroy();
        // The pictures stay until the print dialog has read them.
        window.setTimeout(() => urls.forEach((url) => URL.revokeObjectURL(url)), printed ? 60_000 : 0);
      }
    },
    [],
  );

  const invokePdfBytesPrint = useCallback(
    async (
      bytes: Uint8Array,
      authorityIsCurrent: () => boolean,
    ): Promise<boolean> => {
      if (!authorityIsCurrent()) return false;
      if (!browserShowsPdf()) return invokeRasterPrint(bytes, authorityIsCurrent);
      const blobBytes = new Uint8Array(bytes.byteLength);
      blobBytes.set(bytes);
      if (!authorityIsCurrent()) return false;
      const objectUrl = URL.createObjectURL(
        new Blob([blobBytes], { type: "application/pdf" }),
      );
      const frame = printFrameRef.current;
      if (!frame || !authorityIsCurrent()) {
        URL.revokeObjectURL(objectUrl);
        return false;
      }
      const invoked = await new Promise<boolean>((resolve) => {
        let settled = false;
        const settle = (succeeded: boolean) => {
          if (settled) return;
          settled = true;
          window.clearTimeout(timeoutId);
          frame.onload = null;
          frame.onerror = null;
          resolve(succeeded);
        };
        const timeoutId = window.setTimeout(() => settle(false), 10_000);
        frame.onload = () => {
          if (!authorityIsCurrent()) {
            settle(false);
            return;
          }
          try {
            const printWindow = frame.contentWindow;
            if (!printWindow) {
              settle(false);
              return;
            }
            printWindow.focus();
            if (!authorityIsCurrent()) {
              settle(false);
              return;
            }
            printWindow.print();
            settle(true);
          } catch {
            settle(false);
          }
        };
        frame.onerror = () => settle(false);
        if (!authorityIsCurrent()) {
          settle(false);
          return;
        }
        frame.removeAttribute("srcdoc");
        frame.src = objectUrl;
      });
      if (invoked) setTimeout(() => URL.revokeObjectURL(objectUrl), 1000);
      else URL.revokeObjectURL(objectUrl);
      return invoked;
    },
    [invokeRasterPrint],
  );

  // Continue from the one-shot visible page-size receipt. The same receipt is
  // checked before/after every async boundary and immediately before every
  // publication sink; no later state may inherit an older preflight.
  const executePrintAfterPreflight = useCallback(
    async (receipt: PendingPdfPrintPreflight): Promise<boolean> => {
      if (printing || flattening || loading) return false;
      setPrinting(true);
      const failClosed = () => {
        setFlattenError(t("pdf.viewer.printFailed"));
        return false;
      };
      try {
        if (!printPreflightReceiptIsCurrent(receipt)) return failClosed();

        const hasEdits = receipt.hasEdits;
        if (
          hasEdits &&
          matchedSourceRiskSnapshot &&
          matchedSourceRiskSnapshot.profile.xfa !== "none"
        ) {
          setFlattenError(xfaBlockedReason);
          return false;
        }
        const disposition = hasEdits
          ? ("flatten-with-consent" as const)
          : ("read-only" as const);
        const lossReport = hasEdits
          ? createPdfOutputLossReportForAction("print")
          : createPdfOutputLossReportForAction("download-original");
        const policyRequest = createReaderSavePolicyRequest({
          action: "print",
          disposition,
          hasEdits,
          lossReport,
        });
        const policy = savePolicyV1
          ? resolveReaderSavePolicy(policyRequest)
          : null;
        if (policy && (!policy.view || !policy.view.enabled)) {
          setFlattenError(
            policy.view?.reasonKey ?? t("pdf.viewer.notice.printBlockedByPolicy"),
          );
          return false;
        }
        const consentReceipt =
          policy?.view?.requiresConsent === true
            ? await requestOutputConsent(policyRequest, policy.decision)
            : null;
        if (!printPreflightReceiptIsCurrent(receipt)) return failClosed();
        if (policy?.view?.requiresConsent === true && !consentReceipt) {
          return false;
        }
        if (
          policy?.view?.requiresConsent === true &&
          (!consentReceipt ||
            !consumePdfSavePolicyConsentReceipt({
              receipt: consentReceipt,
              documentAuthority:
                savePolicyRuntimeRef.current.documentAuthority,
              decision: policy.decision,
              currentRequest: createReaderSavePolicyRequest({
                action: "print",
                disposition,
                hasEdits,
                lossReport,
              }),
            }))
        ) {
          return failClosed();
        }
        if (!printPreflightReceiptIsCurrent(receipt)) return failClosed();
        beginOutputAttempt();

        const verifiedSourceBytes =
          await readVerifiedPrintSourceBytes(receipt);
        if (!verifiedSourceBytes) return failClosed();
        if (!printPreflightReceiptIsCurrent(receipt)) return failClosed();

        let outBytes: Uint8Array;
        if (hasEdits) {
          outBytes = await buildAnnotatedPdfBytes({ verifiedSourceBytes });
        } else {
          outBytes = new Uint8Array(verifiedSourceBytes.byteLength);
          outBytes.set(verifiedSourceBytes);
        }
        if (!printPreflightReceiptIsCurrent(receipt)) return failClosed();

        // This is the last semantic operation on the exact bytes. A loader
        // failure, partial inventory, reordered page, changed CropBox or changed
        // /Rotate stops before Blob/URL/iframe/print.
        const finalInventory = await readPdfPrintPageInventory(outBytes);
        if (
          !printPreflightReceiptIsCurrent(receipt) ||
          !pdfPrintPageInventoriesMatch(receipt.inventory, finalInventory)
        ) {
          return failClosed();
        }

        const invoked = await invokePdfBytesPrint(
          outBytes,
          () => printPreflightReceiptIsCurrent(receipt),
        );
        if (!invoked) setFlattenError(t("pdf.viewer.printFailed"));
        return invoked;
      } catch (error) {
        const exportFailureKey = pdfExportFailureMessageKey(error);
        setFlattenError(
          exportFailureKey ? t(exportFailureKey) : t("pdf.viewer.printFailed"),
        );
        return false;
      } finally {
        setPrinting(false);
      }
    },
    [
      beginOutputAttempt,
      buildAnnotatedPdfBytes,
      createReaderSavePolicyRequest,
      flattening,
      invokePdfBytesPrint,
      loading,
      matchedSourceRiskSnapshot,
      printPreflightReceiptIsCurrent,
      printing,
      readVerifiedPrintSourceBytes,
      requestOutputConsent,
      resolveReaderSavePolicy,
      savePolicyV1,
      t,
      xfaBlockedReason,
    ],
  );

  // First Print action is deliberately read-only: capture the exact current
  // document/output authority and show page sizes. It performs no fetch,
  // flatten, Blob, object URL, iframe navigation or print call.
  const handlePrint = useCallback(async (): Promise<boolean> => {
    if (
      pendingPrintPreflightRef.current?.documentAuthority !==
      savePolicyRuntimeRef.current.documentAuthority
    ) {
      pendingPrintPreflightRef.current = null;
    }
    if (
      !annotatedDownloadEnabled ||
      printing ||
      flattening ||
      loading ||
      pendingPrintPreflightRef.current
    ) {
      return false;
    }
    if (redactions.length > 0) {
      setFlattenError(redactionProductCopy.blockedOutput);
      return false;
    }
    const outputAuthority = captureVisualMaskOutputAuthority("print");
    if (!outputAuthority) return false;
    const loaded = loadedPdfSourceIdentityRef.current;
    const source = savePolicyRuntimeRef.current.source;
    const retained = retainedPdfPrintSourceBytesRef.current;
    if (
      !loaded ||
      !source ||
      !retained ||
      loaded.document !== pdfDoc ||
      loaded.dataItemId !== source.identity.dataItemId ||
      loaded.dataItemId !== (dataItemId ?? null) ||
      loaded.url !== url ||
      loaded.byteGenerationKey !== expectedSourceByteGenerationKey ||
      source.identity.byteGenerationKey !== expectedSourceByteGenerationKey ||
      source.identity.documentRevision !== expectedSourceDocumentRevision ||
      retained.document !== loaded.document ||
      retained.dataItemId !== source.identity.dataItemId ||
      retained.url !== loaded.url ||
      retained.byteGenerationKey !== loaded.byteGenerationKey ||
      retained.documentRevision !== source.identity.documentRevision ||
      retained.sha256 !== source.identity.sha256
    ) {
      setFlattenError(t("pdfViewer.flattenFailed"));
      return false;
    }
    try {
      const pending = Object.freeze({
        document: loaded.document,
        dataItemId: source.identity.dataItemId,
        url: loaded.url,
        byteGenerationKey: loaded.byteGenerationKey,
        documentRevision: expectedSourceDocumentRevision,
        sourceSha256: source.identity.sha256,
        documentAuthority: savePolicyRuntimeRef.current.documentAuthority,
        editRevision: savePolicyEditRevisionRef.current.revision,
        hasEdits: hasEffectivePdfOutputEdits,
        outputAuthority,
        inventory: createCurrentPdfPrintInventoryRef.current(),
      }) satisfies PendingPdfPrintPreflight;
      pendingPrintPreflightRef.current = pending;
      setPendingPrintPreflight(pending);
      setFlattenError(null);
      return true;
    } catch {
      setFlattenError(t("pdfViewer.flattenFailed"));
      return false;
    }
  }, [
    annotatedDownloadEnabled,
    captureVisualMaskOutputAuthority,
    dataItemId,
    expectedSourceByteGenerationKey,
    expectedSourceDocumentRevision,
    flattening,
    hasEffectivePdfOutputEdits,
    loading,
    pdfDoc,
    printing,
    redactionProductCopy.blockedOutput,
    redactions.length,
    t,
    url,
  ]);

  const continuePrintPreflight = useCallback(() => {
    const pending = pendingPrintPreflightRef.current;
    if (!pending) return;
    if (!printPreflightReceiptIsCurrent(pending)) {
      cancelPrintPreflight();
      setFlattenError(t("pdfViewer.flattenFailed"));
      return;
    }
    pendingPrintPreflightRef.current = null;
    setPendingPrintPreflight(null);
    void executePrintAfterPreflight(pending);
  }, [
    cancelPrintPreflight,
    executePrintAfterPreflight,
    printPreflightReceiptIsCurrent,
    t,
  ]);

  // ---- File-level merge / split -----------------------------------------
  // The base filename (no extension) used to name merged / split downloads.
  const downloadBaseName = useMemo(
    () => (filename || "document.pdf").replace(/\.pdf$/i, ""),
    [filename],
  );
  const downloadBaseNameRef = useRef(downloadBaseName);
  downloadBaseNameRef.current = downloadBaseName;

  const publishPagePackageOutputs = useCallback(
    (
      outputs: readonly PreparedPdfPagePackageOutput[],
      outputAuthorityIsCurrent: () => boolean,
    ): boolean => {
      for (const output of outputs) {
        if (!outputAuthorityIsCurrent()) return false;
        const safe = new Uint8Array(output.bytes.byteLength);
        safe.set(output.bytes);
        if (!outputAuthorityIsCurrent()) return false;
        const blob = new Blob([safe], { type: "application/pdf" });
        if (!outputAuthorityIsCurrent()) return false;
        startPdfDownload(output.name, blob);
      }
      const last = outputs[outputs.length - 1];
      if (last) {
        if (!outputAuthorityIsCurrent()) return false;
        rememberFileOpResult(last.bytes, last.name);
      }
      return true;
    },
    [rememberFileOpResult, startPdfDownload],
  );

  const executePagePackageOutputs = useCallback(
    async (options: {
      readonly invocation: PdfCommandInvocation;
      readonly action: PdfPagePackageAction;
      readonly sources: readonly PdfPagePackageSourceSnapshot[];
      readonly planDigest: string;
      readonly outputCount: number;
      readonly prepareOutputs: () => Promise<
        readonly PreparedPdfPagePackageOutput[]
      >;
      readonly readCurrentPlanDigest: () => Promise<string>;
    }): Promise<boolean> => {
      if (blockVisualMaskDerivedPdfOutput(options.action)) return false;
      const outputAuthorityIsCurrent =
        createVisualMaskOutputAuthorityGuard(options.action);
      if (!outputAuthorityIsCurrent) return false;
      const pagePackage = createPdfPagePackagePolicyContext({
        sources: options.sources,
        planDigest: options.planDigest,
        outputCount: options.outputCount,
      });
      // What the copied pages leave behind of a tagged, layered or
      // attachment-carrying source is said in the consent, plainly, and
      
      // used to give no file).
      const lossReport = createPdfOutputLossReportForAction(
        options.action,
        options.action === "pdf.file.split" || options.action === "pdf.file.merge" ||
          options.action === "pdf.page.extract"
          ? pdfSourceStructureLossEntries(options.sources.map((entry) => entry.source.profile))
          : [],
      );
      const request = createReaderSavePolicyRequest({
        action: options.action,
        disposition: "flatten-with-consent",
        hasEdits: true,
        lossReport,
        optionRevision: options.planDigest,
        pagePackage,
      });
      const policy = savePolicyV1 ? resolveReaderSavePolicy(request) : null;
      const policyView = policy?.view ?? null;
      if (policy && !policyView?.enabled) {
        setFileOpError(
          policyView?.reasonKey ??
            t("pdf.viewer.notice.pagePackageBlockedByPolicy"),
        );
        return false;
      }
      const outputs = await options.prepareOutputs();
      if (!outputAuthorityIsCurrent()) return false;
      if (outputs.length !== options.outputCount) {
        throw new Error("PDF page-package output plan changed during creation");
      }
      await validatePdfPagePackageOutputs(outputs);
      if (!outputAuthorityIsCurrent()) return false;
      if (!policy) {
        return publishPagePackageOutputs(outputs, outputAuthorityIsCurrent);
      }
      if (!policyView) {
        setFileOpError(t("pdf.viewer.notice.pagePackagePolicyInvalid"));
        return false;
      }
      const operationId = `${commandInstanceId}:page-package:${
        pagePackageOperationGenerationRef.current
      }`;
      const operationOwner = createPdfCommandAuthorityOwner({
        host: "reader",
        instanceId: operationId,
        invocation: options.invocation,
      });
      const authority = operationOwner.bind(async () => {
        if (!outputAuthorityIsCurrent()) return false;
        const consentReceipt = await requestOutputConsent(
          request,
          policy.decision,
        );
        if (!consentReceipt || !outputAuthorityIsCurrent()) return false;
        let currentPagePackage: PdfPagePackagePolicyContext;
        try {
          currentPagePackage = createPdfPagePackagePolicyContext({
            sources: options.sources,
            planDigest: await options.readCurrentPlanDigest(),
            outputCount: options.outputCount,
          });
        } catch {
          return false;
        }
        const currentRequest = createReaderSavePolicyRequest({
          action: options.action,
          disposition: "flatten-with-consent",
          hasEdits: true,
          lossReport,
          optionRevision: currentPagePackage.planDigest,
          pagePackage: currentPagePackage,
        });
        if (
          !consumePdfSavePolicyConsentReceipt({
            receipt: consentReceipt,
            documentAuthority: savePolicyRuntimeRef.current.documentAuthority,
            decision: policy.decision,
            currentRequest,
          })
        ) {
          return false;
        }
        return publishPagePackageOutputs(outputs, outputAuthorityIsCurrent);
      });
      const runtime = {
        featureFlags: readPdfFeatureFlagState(),
        decisions: {
          [options.invocation.featureId]: {
            enabled: true,
            disposition: policyView.disposition,
            savePolicy: { request, decision: policy.decision },
            reasonKey: policyView.reasonKey ?? undefined,
          },
        },
      } satisfies PdfFeatureRuntimeState;
      const context: PdfCapabilityContext = {
        host: "reader",
        documentReady: savePolicyRuntimeRef.current.documentReady,
        editable: savePolicyRuntimeRef.current.editable,
      };
      return (
        (await authority.execute(options.invocation, context, runtime)) ===
        "executed"
      );
    },
    [
      blockVisualMaskDerivedPdfOutput,
      commandInstanceId,
      createReaderSavePolicyRequest,
      createVisualMaskOutputAuthorityGuard,
      publishPagePackageOutputs,
      requestOutputConsent,
      resolveReaderSavePolicy,
      savePolicyV1,
    ],
  );

  // --- Flat-form field detection -----------------------------------------
  // A worksheet exported to PDF has no AcroForm at all. Detection PROPOSES
  // widgets; nothing is written until the proposals have been reviewed, because
  // a heuristic's wrong guesses stay invisible until someone tries to fill the
  // form it silently created.
  const [fieldCandidates, setFieldCandidates] = useState<
    CreateFormFieldCandidate[] | null
  >(null);
  const [rejectedCandidates, setRejectedCandidates] = useState<Set<string>>(
    new Set(),
  );
  const [detectBusy, setDetectBusy] = useState(false);
  const { message: detectNotice, setNotice: setDetectNoticeState } =
    useExpiringNotice<PdfViewerFeedbackMessage>({ ttlMs: PDF_FEEDBACK_TTL_MS });
  const setDetectNotice = useCallback(
    (message: string | null, tone: PdfViewerFeedbackTone = "error") =>
      setDetectNoticeState(message ? { message, tone } : null),
    [setDetectNoticeState],
  );
  const detectedFieldsCommandRef = useRef<HTMLButtonElement | null>(null);
  const [authoredFieldDialogOpen, setAuthoredFieldDialogOpen] = useState(false);
  const existingTextFieldEditCommandRef = useRef<HTMLButtonElement | null>(
    null,
  );
  const existingTextFieldEditReturnFocusRef =
    useRef<HTMLButtonElement | null>(null);
  const [existingTextFieldEditMode, setExistingTextFieldEditMode] =
    useState(false);
  const [existingTextFieldEditSession, setExistingTextFieldEditSession] =
    useState<ExistingFormFieldEditSession | null>(null);
  const existingTextFieldEditSessionRef =
    useRef<ExistingFormFieldEditSession | null>(null);
  existingTextFieldEditSessionRef.current = existingTextFieldEditSession;
  const [selectedFormFieldContext, setSelectedFormFieldContext] =
    useState<SelectedFormFieldContext | null>(null);
  const selectedFormFieldContextRef =
    useRef<SelectedFormFieldContext | null>(null);
  selectedFormFieldContextRef.current = selectedFormFieldContext;
